export interface DemoEntry {
  name: string
  title: string
  description: string
  category: string
  Demo: ComponentType
}

export const demos: DemoEntry[] = [
  { name: "agent-action-approve", title: "Agent Action Approve", description: "Stops an AI agent's tool call from doing something nobody approved by reading the call itself and saying in plain words what it will delete, send or change, how far that reaches (one file up to a whole drive or production) and whether it can be undone, marking the one token that changes everything (a lone \\ that means the drive root, an unset $VAR, ../, a C:/Users/ALEX~1 short name), setting what the agent said beside what the call does when they disagree, checking MCP read-only labels against the call, reading inside bash -c, cmd /c and encoded PowerShell, flagging curl | bash, making dangerous calls hold-to-approve, and showing what an \"always allow\" rule would also let through while refusing one for npx, bash -c, chained commands and anything irreversible.", category: "Destructive actions", Demo: AgentActionApproveDemo },
  { name: "mcp-tool-review", title: "MCP Tool Review", description: "Stops an MCP rug pull, where a server changes its tools after you approved them, by fingerprinting each tool definition, diffing the new description word by word against the approved one, marking the poisoned phrases inside the added text (<IMPORTANT> blocks, \"do not tell the user\", ~/.ssh and mcp.json, instructions about another server's send_email), flagging new free-text parameters that could carry data out, invisible characters and read-only labels that flipped, and letting the person keep the approved version, turn the tool off or accept the change, with a second press for anything suspicious and a one-tap accept for the safe ones.", category: "Destructive actions", Demo: McpToolReviewDemo },
  { name: "reset-hard-readback", title: "Reset Hard Readback", description: "Stops git reset --hard, git clean -fdx, git checkout -- . and git stash drop from silently destroying work by reading porcelain status and listing exactly what will be lost (edited files with +/- lines, staged new files, untracked and ignored files with .env and keys first, commits the branch moves past with unpushed ones marked, stash entries with the id to recover them), saying what stays, and offering to stash first.", category: "Destructive actions", Demo: ResetHardReadbackDemo },
  { name: "account-deletion-readback", title: "Account Deletion Readback", description: "Stops an account deletion that loses more than the user expects or keeps charging them: before Delete it reads back what goes, teams left with no owner (with a transfer button), App Store and Google Play subscriptions that keep billing until cancelled there, the date it can be restored until, what the law keeps and a data export, and unlocks Delete only after a typed confirmation, labelled \"Delete without export\" until a copy is taken, and lets the user schedule deletion for when a paid period ends instead of losing paid time.", category: "Destructive actions", Demo: AccountDeletionReadbackDemo },
  { name: "force-push-confirm", title: "Force Push Confirm", description: "Stops a force push from silently deleting work on the remote by listing every commit it would drop with author, message and age, marking other people's commits (co-authors and GitHub noreply addresses included) and protected branches, building a --force-with-lease command pinned to the tip you were shown (or --force-if-includes, so an IDE's background fetch can't defeat the lease), and asking you to type the branch name only when someone else's work would be lost.", category: "Destructive actions", Demo: ForcePushConfirmDemo },
  { name: "infra-plan-readback", title: "Infra Plan Readback", description: "Stops a Terraform or OpenTofu apply from quietly destroying data by reading the `terraform show -json` plan back as create, update, replace and destroy counts, putting destroys and replacements of databases, buckets, volumes and keys first with the attribute that forces each replacement (before → after, sensitive values hidden), whether the old one goes before its replacement exists and what force_destroy or skip_final_snapshot will do, flagging production workspaces and a var.environment that says production when the workspace doesn't, and keeping Apply locked until each data loss is acknowledged and, in production, the workspace name is typed.", category: "Destructive actions", Demo: InfraPlanReadbackDemo },
  { name: "recovery-contact-cooldown", title: "Recovery Contact Cooldown", description: "Stops account takeovers that start by swapping the recovery email or phone by making the security hold visible: it says what the contact is changing to (masked), drains a countdown to when it takes effect, notes that codes still go to the old contact meanwhile, turns urgent in the last hour, and offers a one-tap cancel plus a \"this wasn't me\" path, announcing only the outcome, never the ticking.", category: "Destructive actions", Demo: RecoveryContactCooldownDemo },
  { name: "migration-preview", title: "Migration Preview", description: "Stops migrations that take production down or lose data by reading Postgres SQL back step by step (strings, dollar quotes and comments handled), showing what each step locks and whether it touches every row of a big table, marking dropped tables and columns as impossible to undo, and catching NOT NULL columns that will fail, renames that break code mid-deploy, CONCURRENTLY inside a transaction and a missing lock_timeout, with a one-tap safer sequence and undo.", category: "Destructive actions", Demo: MigrationPreviewDemo },
  { name: "feature-flag-rollout", title: "Feature Flag Rollout", description: "Prevents a risky flag release by reading back exactly who gets it (segments plus a percentage of everyone else, in users), asking for a second click before production skips ramp steps or gets ahead of staging, and warning how many users lose the feature on a pullback.", category: "Destructive actions", Demo: FeatureFlagRolloutDemo },
  { name: "branch-target", title: "Branch Target", description: "Prevents merging or deploying into the wrong place by checking the chosen base against branch rules (feature → main is caught, with a one-tap switch to develop), counting commits the branch drags in that aren't its own, and flagging a head that is behind its target with an Update branch action.", category: "Destructive actions", Demo: BranchTargetDemo },
  { name: "session-list", title: "Session List", description: "Stops people signing themselves out while cleaning up sessions: this device is pinned and marked, \"Sign out all others\" can never include it, signing out here asks once inline with Cancel focused, and sessions from another country are flagged with honest \"approximate location\" wording.", category: "Destructive actions", Demo: SessionListDemo },
  { name: "sign-in-approve", title: "Sign-in Approve", description: "Stops MFA-fatigue approvals: there is no one-tap Approve, the user must type the number from the sign-in screen, and the prompt shows location and device, warns about request bursts and numbers sent by \"support\", refuses after wrong guesses and ends every denial on a secure-my-account step.", category: "Destructive actions", Demo: SignInApproveDemo },
  { name: "hold-to-confirm", title: "Hold to Confirm", description: "Prevents stray clicks and taps from triggering destructive actions: the button fires only after a full press-and-hold (mouse, touch or keyboard), rewinds on early release, shows \"Hold to confirm\" when someone just clicks, and lets screen reader and switch users, who can't hold, confirm with a second press instead.", category: "Destructive actions", Demo: HoldToConfirmDemo },
  { name: "two-step-button", title: "Two-Step Button", description: "Prevents one-click destruction: the first click arms the button with a draining timer, a second deliberate click confirms, and accidental double-clicks, held keys, blur, Escape or the timeout all disarm it.", category: "Destructive actions", Demo: TwoStepButtonDemo },
  { name: "slide-to-confirm", title: "Slide to Confirm", description: "Prevents accidental taps and pocket presses from sending payments or ending sessions: the thumb must travel the whole track, a held arrow key stops short, and an async confirm shows a pending state.", category: "Destructive actions", Demo: SlideToConfirmDemo },
  { name: "type-to-confirm", title: "Type to Confirm", description: "Prevents deleting the wrong thing on reflex: a GitHub-style dialog that unlocks only after the exact phrase is typed, highlighting the matched characters and flagging a typo as it happens.", category: "Destructive actions", Demo: TypeToConfirmDemo },
  { name: "undo-toast", title: "Undo Toast", description: "Prevents irreversible mistakes without an \"Are you sure?\": actions run optimistically and only commit after an undo window with a countdown ring that pauses on hover, focus or a hidden tab, Ctrl/⌘+Z, a commit when the page closes, and a rollback with a clear notice when the commit fails.", category: "Destructive actions", Demo: UndoToastDemo },
  { name: "impact-preview", title: "Impact Preview", description: "Prevents surprise cascade deletes by loading and listing everything that goes with a parent object, grouped by type with counts and samples and marked deleted, detached or kept, and keeps Confirm locked until the list loads.", category: "Destructive actions", Demo: ImpactPreviewDemo },
  { name: "bulk-scope-confirm", title: "Bulk Scope Confirm", description: "Prevents bulk actions from hitting more than intended by stating the exact count and risky subsets, defaulting to only this page, and locking Confirm if the match count changes while it is open.", category: "Destructive actions", Demo: BulkScopeConfirmDemo },
  { name: "cooldown-button", title: "Cooldown Button", description: "Prevents resend spam and double charges by enforcing escalating cooldowns per attempt (30s, 60s, 120s) with a visible countdown and reason, persisted in sessionStorage so a refresh can't bypass it.", category: "Destructive actions", Demo: CooldownButtonDemo },
  { name: "safe-submit", title: "Safe Submit", description: "Stops double charges and duplicate records by collapsing repeated clicks, Enter spam and double-taps into one request, with an idempotency key that is reused on retry after a network error.", category: "Destructive actions", Demo: SafeSubmitDemo },
  { name: "drop-confirm", title: "Drop Confirm", description: "Stops accidental drag-and-drop moves: the target names exactly what will move and where, ignores a drop that lands before the pointer has rested on it, asks once before large moves or moves that change who can see the items, and offers Undo, with a Move here button for keyboard and touch.", category: "Destructive actions", Demo: DropConfirmDemo },
  { name: "danger-zone", title: "Danger Zone", description: "Stops a stray click in settings from deleting or transferring something: destructive actions stay listed with their consequences but locked until the user deliberately unlocks the section, which locks itself again after one action, an idle timeout, Escape, a hidden tab or focus leaving it.", category: "Destructive actions", Demo: DangerZoneDemo },
  { name: "click-shield", title: "Click Shield", description: "Stops clicks that land on a button only because it just appeared, shifted under the cursor or changed its label, by ignoring pointer presses for ~500ms with a quiet fade-in cue, while keyboard users are only shielded from focus that code moved onto the button.", category: "Destructive actions", Demo: ClickShieldDemo },
  { name: "shortcut-confirm", title: "Shortcut Confirm", description: "Stops a slipped finger from firing a destructive keyboard shortcut: the first press only shows \"Press ⌘⌫ again to delete 3 items\", and only a separate second press within the window confirms, never a held key, an extra modifier, a stray key in between or a keystroke meant for a text field.", category: "Destructive actions", Demo: ShortcutConfirmDemo },
  { name: "guarded-switch", title: "Guarded Switch", description: "Stops a critical setting like maintenance mode or a kill switch being flipped by a stray click: a see-through cover, like an aircraft switch guard, must be lifted first, says what flipping will do while it's up, drops back on its own, and reads back the consequence after the change.", category: "Destructive actions", Demo: GuardedSwitchDemo },
  { name: "swipe-delete-row", title: "Swipe Delete Row", description: "Prevents accidental swipe-deletes: the row only deletes when dragged past a visible line (not by a fast flick or a vertical scroll), resists like a rubber band, springs back if released early, has a trash button for keyboard users, and keeps an Undo before the delete commits.", category: "Destructive actions", Demo: SwipeDeleteRowDemo },
  { name: "grace-send", title: "Grace Send", description: "Catches the regretted send: pressing Send starts a short countdown with a draining ring before the irreversible action fires, so Cancel, Escape or a leave-page warning can stop it, while Send now skips the wait.", category: "Destructive actions", Demo: GraceSendDemo },
  { name: "bulk-runner", title: "Bulk Runner", description: "Stops bulk jobs from ending in \"some of it happened, probably\": live done/failed/remaining counts, Pause and Stop that let in-flight items finish and then say exactly what was and wasn't done, failures grouped by reason with retry-failed-only, and a progress bar that never jumps backwards.", category: "Destructive actions", Demo: BulkRunnerDemo },
  { name: "two-person-approve", title: "Two-Person Approve", description: "Enforces the two-person rule for high-risk actions: the requester can't approve their own request, approval is bound to a fingerprint of exactly what will run so an edited plan has to be re-reviewed, rejections need a reason, and expired requests can't be approved.", category: "Destructive actions", Demo: TwoPersonApproveDemo },
  { name: "trash-countdown", title: "Trash Countdown", description: "Stops things vanishing for good by surprise: trashed items show how long until they're deleted forever, soon-to-purge items are highlighted, restore is one tap, and emptying the trash needs the typed item count, which resets if new items arrive mid-confirmation.", category: "Destructive actions", Demo: TrashCountdownDemo },
  { name: "range-select-guard", title: "Range Select Guard", description: "Catches runaway shift-click selections: it reads back how many rows a range just selected with Undo, skips and reports rows hidden by the filter, flags rows on pages you never opened with an 'only this page' fix, and calls out selected rows a filter has hidden.", category: "Destructive actions", Demo: RangeSelectGuardDemo },
  { name: "reauth-gate", title: "Reauth Gate", description: "Sudo mode for sensitive actions: it asks for a passkey, password or PIN through your own verify function, names the exact action and why it's asking, runs the queued action right after confirmation, and remembers it for a short window shown as a countdown chip you can end early.", category: "Destructive actions", Demo: ReauthGateDemo },
  { name: "rollback-preview", title: "Rollback Preview", description: "Prevents rollbacks that undo more or less than you expect by listing what reverts, what won't undo (irreversible migrations, data written since), the target's age and every newer version it skips, and confirming only when you type the target's name, calling out a different version's name instead of silently not matching.", category: "Destructive actions", Demo: RollbackPreviewDemo },
  { name: "edit-lock", title: "Edit Lock", description: "Prevents accidental edits to finished or approved records by locking the form in a disabled fieldset (\"Locked by Priya after approval\"), stating before unlocking that any change needs re-approval, voiding the approval only when something actually changes, and relocking itself after a stretch of idleness, never mid-typing.", category: "Destructive actions", Demo: EditLockDemo },
  { name: "spend-cap-button", title: "Spend Cap Button", description: "Prevents duplicate purchases and overspending: it remembers recent buys of the same item (\"You bought this 3 min ago\", including a double-click a second ago) and needs a deliberate second click to buy again, previews this purchase as a slice of each daily or monthly cap, and blocks any spend that would break a cap with the overage and when it resets.", category: "Destructive actions", Demo: SpendCapButtonDemo },
  { name: "scheduled-queue", title: "Scheduled Queue", description: "Prevents scheduled sends going out wrong or unnoticed: each row counts down live, the last-chance window highlights and counts down to the real cancel cutoff (when the provider locks the send in), sends landing in quiet hours where the audience lives get a one-tap move to a sane hour, missed sends are flagged, and rescheduling refuses a time in the past.", category: "Destructive actions", Demo: ScheduledQueueDemo },
  { name: "archive-or-delete", title: "Archive or Delete", description: "Stops someone from permanently deleting what they only meant to put away: Archive and Delete sit side by side with each affected thing's honest fate under both, the reversible choice starts selected and focused so Enter archives, and picking Delete flashes what is lost and relabels the button \"Delete forever\".", category: "Destructive actions", Demo: ArchiveOrDeleteDemo },
  { name: "revoke-access-preview", title: "Revoke Access Preview", description: "Stops a member, token or app removal from silently orphaning their work and breaking things: it lists what they lose, what they own with a reassign-to picker and one-tap reassign-all, sessions that end now (flagging any in use this minute) and integrations that stop because they run on that person's credentials, and the button says if anything will be left unowned.", category: "Destructive actions", Demo: RevokeAccessPreviewDemo },
  { name: "transfer-ownership", title: "Transfer Ownership", description: "Stops ownership landing on the wrong person or the wrong plan: it reads back what moves and what you keep, warns when the email is outside your org with a one-tap switch to the colleague you probably meant, blocks a recipient whose plan can't own it, and only transfers once they accept, showing the pending request and its expiry meanwhile.", category: "Destructive actions", Demo: TransferOwnershipDemo },
  { name: "cancel-readback", title: "Cancel Readback", description: "Stops people cancelling blind, or being tricked out of it: the cancel screen reads back the exact date and time access ends, what is lost and kept and the refund (or plainly that there is none), offers pause or downgrade once below a cancel button that never moves, and ends on a receipt with an undo.", category: "Destructive actions", Demo: CancelReadbackDemo },
  { name: "merge-records", title: "Merge Records", description: "Stops a duplicate merge from silently throwing data away: each field defaults to the most recent non-empty value, real conflicts are marked (ignoring case and spacing), and a live readback names every value that will be discarded, which record keeps its ID, and which links move to it.", category: "Destructive actions", Demo: MergeRecordsDemo },
  { name: "move-readback", title: "Move Readback", description: "Stops a move from quietly changing who can see something: it reads back the destination path with the folder that sets access highlighted, says how many people gain or lose access (\"Moving into Public makes it visible to 40 people\"), counts path links that will break with a one-tap redirect, lists inherited settings that change, and relabels the button when the move widens the audience.", category: "Destructive actions", Demo: MoveReadbackDemo },
  { name: "reset-preview", title: "Reset Preview", description: "Stops \"Reset to defaults\" from wiping customizations nobody looked at: it lists only the settings the user changed as current → default, lets them keep any, warns with a one-tap export until a copy is saved, and offers a draining Undo after the reset.", category: "Destructive actions", Demo: ResetPreviewDemo },
  { name: "replace-file", title: "Replace File", description: "Stops an upload from overwriting a newer file with an older one: each name clash shows both copies side by side with thumbnail, size and date (newer and larger in bold), warns with a one-tap \"Keep both\" when an older file would replace a newer one, spots identical copies, previews the renamed copy, and applies one choice to all with counts while saying the other files upload as normal.", category: "Destructive actions", Demo: ReplaceFileDemo },
  { name: "dns-record-guard", title: "DNS Record Guard", description: "Stops a DNS edit or delete from quietly breaking things by checking it against the whole zone before saving: email that stops (a removed MX, SPF senders dropped or doubled past the 10-lookup limit, a DKIM selector removed, escalated when the DMARC policy enforces it), a CNAME at the root or beside other records and names left pointing at nothing, then saying how long the change takes to spread with a one-tap “lower TTL first” that counts down until old caches clear.", category: "Destructive actions", Demo: DnsRecordGuardDemo },
  { name: "key-rotate", title: "Key Rotate", description: "Stops an API key rotation from taking production down by keeping old and new keys valid until a stated time, showing which clients have been seen on the new key, flagging jobs that won't call again before the old key expires with a one-tap longer window, and blocking an immediate cut-off while the old key is still in use unless you say it leaked.", category: "Destructive actions", Demo: KeyRotateDemo },
  { name: "retention-change", title: "Retention Change", description: "Stops a shorter data-retention period from destroying data by surprise by saying exactly what goes and when (“Lowering to 30 days deletes 14,210 events older than 13 Sep, tonight at 02:00”), shading the doomed days on a chart, counting down to the purge while changing it back still loses nothing, and naming the confirm button “Delete without export” until an export-first is done.", category: "Destructive actions", Demo: RetentionChangeDemo },
  { name: "seat-reduce", title: "Seat Reduce", description: "Stops a lower seat count from cutting people off silently by making you choose who goes, suggesting unaccepted invites first and then the least active members (never the owner or admins), calling out an admin or someone active today if you pick them, and showing the new bill, when it starts and what happens to each person's work before you confirm.", category: "Destructive actions", Demo: SeatReduceDemo },
  { name: "fx-send-receive", title: "FX Send Receive", description: "Stops an international payment arriving short by locking the side you typed (send or receive), measuring what actually arrives against the invoice, and catching the invoice figure typed into \"You send\", an invoice in another currency, SHA bank deductions on the way and overpaying, each fixed in one tap by sliding the lock to \"They receive\" at the exact amount or switching charges to OUR.", category: "Inputs that catch typos", Demo: FxSendReceiveDemo },
  { name: "leftover-text-check", title: "Leftover Text Check", description: "Stops text being published with the parts nobody meant to keep: chatbot chatter and refusals (\"I cannot fulfill that request\"), unfilled placeholders ([product], [task 1], XX%), TK and TODO markers and a paragraph pasted twice, with no false alarms on [1], [sic] or Markdown links, flagging them the moment they are pasted, deleting a chatter sentence in one tap, filling every copy of a placeholder at once, and asking for a second press to publish with leftovers.", category: "Inputs that catch typos", Demo: LeftoverTextCheckDemo },
  { name: "ai-citation-check", title: "AI Citation Check", description: "Stops made-up references going out in AI-written text by flagging the tells with a reason for each (a DOI prefix that doesn't belong to the journal it names, a long dash inside a DOI, a case cited to F.3d for a year after 2021, a year that hasn't happened, leftover oaicite and 【4†source】 markers, long quotes with nothing saying who said them), looking every DOI, case and link up through a pluggable verify such as Crossref or CourtListener, calling anything it couldn't confirm \"Unverified\" rather than fine, fixing dashes and markers in one tap, and asking for a second press to submit with references that may not exist.", category: "Inputs that catch typos", Demo: AiCitationCheckDemo },
  { name: "commit-combobox", title: "Commit Combobox", description: "Stops a pick-from-list field saving text the user only typed, or a stale pick they typed over: unpicked text is matched on blur (an exact match is picked, a misspelling gets a one-tap Did you mean, two same-named options ask which), editing after a pick visibly drops it with Undo or Esc, and the stored option is always read back.", category: "Inputs that catch typos", Demo: CommitComboboxDemo },
  { name: "relative-date-input", title: "Relative Date Input", description: "Stops a date typed the way people say it from landing on the wrong day: \"next Fri\", \"in 2 weeks\", \"the 15th\" and \"23 Oct\" are read with date-fns against today, and phrases that split listeners (\"next Friday\" on a Wednesday, \"this Monday\" after Monday, \"the 10th\" once it has passed, \"next weekend\" early in the week) show both dates and wait for a pick, with a read-back and a one-tap rewrite to the unambiguous date.", category: "Inputs that catch typos", Demo: RelativeDateInputDemo },
  { name: "namesake-select", title: "Namesake Select", description: "Stops “right name, wrong person” picks (the second Ravi Kumar one row down, a patient or customer with a twin) by flagging options that share a name regardless of case, accents or word order with only the details that tell them apart, asking for one identifier among the namesakes before a shared name becomes the value (the ID re-entry that cut wrong-patient orders most in a randomized trial), offering a one-tap switch when the answer belongs to the other person, reading the choice back with two identifiers and calling out identical records as likely duplicates, in a list that flips and shrinks instead of clipping.", category: "Inputs that catch typos", Demo: NamesakeSelectDemo },
  { name: "k8s-resource-input", title: "K8s Resource Input", description: "Stops Kubernetes requests and limits that the API rejects or quietly misreads by reading each value back in plain units and catching CPU 500 meaning 500 cores, 400m of memory meaning 0.4 bytes, 512MB and other case-sensitive unit slips, a 1G limit sitting under a 1Gi request, CPU finer than 1m (rounded up) and requests bigger than any node, each with a one-tap fix, plus the pod's QoS class and a pasted resources: block filling all four fields.", category: "Inputs that catch typos", Demo: K8sResourceInputDemo },
  { name: "connection-string-input", title: "Connection String Input", description: "Stops a database URL that fails to connect or connects insecurely by masking the password whenever it isn't being edited, reading back the user, host, database and TLS mode the driver will really use, and catching an unencoded @, #, / or % in the password (naming the host a strict parser would try instead), localhost in production, a missing, weak or misspelled sslmode, unknown libpq parameters, a port that belongs to another database, redis:// and MongoDB URLs without TLS (including mongodb+srv:// with tls=false), sslrootcert=system with a weaker sslmode, a colon in a MongoDB password, and quotes or KEY= pasted from a .env file, each with a one-tap fix and a copy-without-password button.", category: "Inputs that catch typos", Demo: ConnectionStringInputDemo },
  { name: "epoch-input", title: "Epoch Input", description: "Stops a timestamp field storing the wrong moment by reading the value back as a date in the user's zone and in UTC, and catching milliseconds pasted where seconds belong (year 57,754), microseconds and nanoseconds, Excel serials, Windows FILETIME and .NET ticks, ISO strings with no time zone that JavaScript reads as local time and servers as UTC, date-only strings read as UTC midnight, impossible dates like 30 February, years and compact dates (2026, 20261014) that silently read as 1970, and values past the 2038 limit of 32-bit time, each with a one-tap conversion and copy-as seconds, milliseconds or ISO.", category: "Inputs that catch typos", Demo: EpochInputDemo },
  { name: "package-name-check", title: "Package Name Check", description: "Stops an npm or pip install pulling in a typosquat by reading the install command or requirements list package by package and catching lookalikes of popular packages (loadsh, crossenv, cross-env.js, jeIlyfish with a capital I, colourama), import names that aren't the package to install (sklearn, cv2, bs4, PIL), built-ins installed from the registry (fs, crypto, json), names npm or PyPI can't publish, and, through an optional registry lookup, names that don't exist yet (the AI-hallucination trap) or appeared days ago with almost no downloads, each with a one-tap switch to the real package.", category: "Inputs that catch typos", Demo: PackageNameCheckDemo },
  { name: "cheque-check", title: "Cheque Check", description: "Stops a cheque being deposited after it expires, before its date or with a correction clearing will reject, by reading the date the way it's written in the CTS boxes (so 31 November is caught), showing the safe deposit window under RBI's 3-month rule and warning on the disputed last day, catching a January cheque still carrying last year's date and a two-digit year, and saying when Positive Pay is needed, with one-tap date fixes.", category: "Inputs that catch typos", Demo: ChequeCheckDemo },
  { name: "kyc-name-match", title: "KYC Name Match", description: "Stops a KYC or PAN–Aadhaar submission failing on a name that doesn't match the documents, by comparing the typed name with each document word by word (order, initials, a missing middle name, transliterations like Laxmi and Lakshmi), checking the PAN's 4th and 5th letters against the holder type and surname, flagging a date of birth or gender that differs between documents (which UIDAI says must be identical), and offering each document's exact name in one tap.", category: "Inputs that catch typos", Demo: KycNameMatchDemo },
  { name: "aadhaar-input", title: "Aadhaar Input", description: "Prevents rejected KYC and over-exposed Aadhaar numbers by masking the entry as XXXX XXXX 1234 while typing (reveal on demand), checking the Verhoeff digit and the never-0-or-1 first digit, offering a one-tap reveal when the check digit fails (instead of guessing a swap that is often wrong), recognising a VID, the 28-digit enrolment ID, a masked copy, a PAN or a mobile number (with or without +91) pasted by mistake, cleaning photocopy spaces and dashes, and saying that a VID or masked number is enough and how the number is stored.", category: "Inputs that catch typos", Demo: AadhaarInputDemo },
  { name: "cache-control-input", title: "Cache Control Input", description: "Stops cache headers from leaking or stranding content by reading back who stores the response and for how long (browser, CDN via CDN-Cache-Control or Surrogate-Control, other shared caches) and flagging per-user pages a CDN can cache, a cookie-setting response made public, no-cache mistaken for no-store, immutable on URLs that keep their name, a missing Vary for compressed or negotiated bodies and HTML kept for days, each with a one-tap fix.", category: "Inputs that catch typos", Demo: CacheControlInputDemo },
  { name: "password-policy-input", title: "Password Policy Input", description: "Stops admins shipping password rules that make accounts weaker by reading the policy back against NIST SP 800-63B-4: it flags banned composition rules, forced rotation, security questions and hints, minimums under 15 (8 with MFA), maximums under 64, blocked paste, no breached-password check and no failed-sign-in limit, shows what the rules do to real passwords (Password1! accepted, a long passphrase refused), and fixes each rule or applies NIST defaults in one tap.", category: "Inputs that catch typos", Demo: PasswordPolicyInputDemo },
  { name: "mrz-paste-input", title: "MRZ Paste Input", description: "Stops misread passport details reaching a booking or KYC form by validating a pasted or typed passport MRZ (ICAO 9303 TD3) check digit by check digit, catching OCR slips like O for 0 and K for <, swapped lines, CRLF and stray spaces, proposing the likeliest fix for a wrong check digit (cross-checked against the composite digit) and flagging an expired or soon-expiring passport, then filling in name, number, nationality, dates and sex.", category: "Inputs that catch typos", Demo: MrzPasteInputDemo },
  { name: "notice-period-check", title: "Notice Period Check", description: "Stops people resigning towards the wrong last day by working it out from the resignation and the notice policy (days, weeks or months, calendar or working days, notice from the same or the next day) and flagging month-end arithmetic like 31 Jan + 1 month, a last day on a weekend or holiday, an email HR dates differently in its own time zone, unpaid leave pushing the date out, leave set-off and the buyout cost of leaving early, with one-tap fixes and a line to copy to HR.", category: "Inputs that catch typos", Demo: NoticePeriodCheckDemo },
  { name: "tax-regime-compare", title: "Tax Regime Compare", description: "Stops salaried people in India picking the tax regime that costs them more by working out tax year 2026-27 tax under the old and new regimes from salary, HRA (with the 8 cities at 50% under rule 279), 80C, 80D, NPS and home-loan interest, showing the break-even deductions, and flagging a choice that costs more, deductions that don't count under the new regime and claims over their limit, each with a one-tap fix.", category: "Inputs that catch typos", Demo: TaxRegimeCompareDemo },
  { name: "curl-pipe-guard", title: "Curl Pipe Guard", description: "Stops an install one-liner from running a script you didn't mean to trust by showing, before a curl | sh (or wget, or iwr | iex) is copied or run, the script's real host and flagging plain http, raw IPs, shortened links, a host that isn't the product's docs domain, sudo, -k/--insecure, a missing checksum and a missing -f, then offering the same install as download, inspect, verify and run steps to copy instead.", category: "Inputs that catch typos", Demo: CurlPipeGuardDemo },
  { name: "port-expose-guard", title: "Port Expose Guard", description: "Stops a database or admin port being published to the internet by accident: it reads a docker run command, compose ports or a Kubernetes Service back as who can reach each port, flags databases bound to 0.0.0.0 (which Docker opens ahead of ufw), host networking, -P, NodePort or public LoadBalancer for internal services, a container port the image doesn't listen on and unquoted 22:22 that YAML reads as 1342, and fixes each in one tap (bind to 127.0.0.1, ClusterIP, the right port, quotes). It reads ${VAR} ports, long and { … } compose syntax and [::] binds, keeps CRLF line endings, and notes that 127.0.0.1 was LAN-reachable before Docker 28.", category: "Inputs that catch typos", Demo: PortExposeGuardDemo },
  { name: "passenger-name-input", title: "Passenger Name Input", description: "Prevents denied boarding and name-change fees by checking a flight or train passenger name against the ID, catching swapped names, a missing middle name, a title, suffix or nickname typed into the name, single-name passengers, accents the ticket can't print and names over the airline's limit, each with a one-tap fix, and reading it back as SURNAME/GIVEN TITLE the way it will print.", category: "Inputs that catch typos", Demo: PassengerNameInputDemo },
  { name: "emi-readback", title: "EMI Readback", description: "Stops a borrower signing for the wrong loan by reading back EMI, total interest, processing fee with GST, other upfront charges, what actually reaches the account and the real yearly cost (APR, computed the way RBI's Key Facts Statement does), catching tenure typed in months when years were meant (and the reverse), a monthly rate typed as yearly, a flat rate that hides a far higher reducing rate and fees that eat the loan, each with the EMI both ways and a one-tap fix, plus what a prepayment saves.", category: "Inputs that catch typos", Demo: EmiReadbackDemo },
  { name: "leave-request-check", title: "Leave Request Check", description: "Stops a time-off request costing more (or meaning something else) than the person thinks by reading it back day by day as calendar days, working days and the leave it really uses, and flagging weekends and holidays at the ends, a sandwich rule from your policy that charges the weekend in between, a half day with no half chosen or one that leaves a working gap, a balance going negative and teammates already away, with one-tap fixes and the date they're back at work.", category: "Inputs that catch typos", Demo: LeaveRequestCheckDemo },
  { name: "photo-spec-check", title: "Photo Spec Check", description: "Stops exam, passport and visa photos being rejected after upload by checking them against the portal's rules (UPSC, SSC, NTA, NEET and US visa presets, or your own): the real file type behind the name, KB, pixels, shape, print size, over-compression, face size and centring when a face box is passed, a background that isn't white and black-and-white photos, with a one-tap canvas fix that crops around the face, resizes and re-encodes into the KB window.", category: "Inputs that catch typos", Demo: PhotoSpecCheckDemo },
  { name: "doc-upload-match", title: "Doc Upload Match", description: "Stops a KYC upload being rejected days later by checking the file against the document asked for (Aadhaar back instead of front, Aadhaar in the PAN slot, a password-locked e-Aadhaar PDF with its password rule, a multi-page PDF, a tiny, blurry or HEIC photo, a screenshot of a screenshot) from cheap in-browser signals plus an optional classify hook, and saying exactly what to upload instead.", category: "Inputs that catch typos", Demo: DocUploadMatchDemo },
  { name: "ai-paste-guard", title: "AI Paste Guard", description: "Stops hidden prompt injections riding in on a paste: it reads the HTML clipboard data pasted into an AI prompt box, holds the paste when it carries text the person couldn't see (white or same-colour text, zero-size or transparent text, display:none, off-screen and clipped elements, HTML comments, alt or title text with instructions, Unicode tag-character payloads decoded back to ASCII) while ignoring the clipboard's own StartFragment and Word markers, framework comments (WordPress, React, Vue, Angular), gradient text, screen-reader-only labels and light text copied from dark-mode pages (inferred when most of the paste is light, so white-on-white injections still show), shows each passage with injection phrasing marked and whether it would reach a plain-text box, and pastes only the visible text in one tap with an undo.", category: "Inputs that catch typos", Demo: AiPasteGuardDemo },
  { name: "ssh-key-input", title: "SSH Key Input", description: "Stops a private key being pasted where a public key belongs by saying so loudly, telling the user to rotate it and pulling out the public half in one tap, and catches DSA and short RSA keys, keys wrapped across lines or cut off, a missing or wrong type prefix, the SSH2 export format and a key already on the account, showing the SHA256 fingerprint and comment exactly as ssh-keygen prints them.", category: "Inputs that catch typos", Demo: SshKeyInputDemo },
  { name: "jwt-inspect", title: "JWT Inspect", description: "Stops live tokens being pasted into online decoders by decoding on the page only, and flags alg none, HS-vs-RS key confusion, an expired token or a future nbf shown in the reader's own time zone, millisecond timestamps, a missing aud or iss, a very long lifetime and secrets or personal data readable in the payload.", category: "Inputs that catch typos", Demo: JwtInspectDemo },
  { name: "cert-paste-check", title: "Cert Paste Check", description: "Stops a broken TLS install by telling a certificate from a private key from a CSR as they are pasted, and catching a chain out of order or missing its intermediate, an expired or soon-expiring certificate, a domain the SANs don't cover (wildcard and CN-only traps included), a self-signed certificate in production and a private key that doesn't match, with one-tap reorder and remove fixes.", category: "Inputs that catch typos", Demo: CertPasteCheckDemo },
  { name: "chmod-input", title: "Chmod Input", description: "Stops permission mistakes that leak data or lock people out by reading any mode (644, 0755, u+x, -rwxr-xr-x) back as rwx and plain words, and flagging world-writable files, setuid and setgid, private keys and .env files others can read, a writable ~/.ssh or authorized_keys, execute bits on data files, 775 typed for 755, and short or decimal modes, each with a one-tap safe mode.", category: "Inputs that catch typos", Demo: ChmodInputDemo },
  { name: "email-change-guard", title: "Email Change Guard", description: "Stops people locking themselves out by changing their account email to a typo: it catches misspelled providers (gmial.con) with a one-tap fix, shows exactly where the confirmation stops matching, spots the same inbox (Gmail dots, +tags), says what moves with the address (sign-in, receipts, 2FA codes), and keeps the old address active until the new one is verified, with resend, edit and cancel while it waits.", category: "Inputs that catch typos", Demo: EmailChangeGuardDemo },
  { name: "redirect-uri-input", title: "Redirect URI Input", description: "Prevents redirect_uri_mismatch sign-in failures and leaked authorization codes by checking a redirect URI the way an OAuth server does, exact string match, so it catches a trailing slash, http versus https, letter case, www or a port that differs from the registered list (with the differing characters highlighted side by side and a one-tap swap), plus localhost in production, wildcards, a default :443 port or empty ?, a #fragment, stray whitespace and short custom schemes.", category: "Inputs that catch typos", Demo: RedirectUriInputDemo },
  { name: "csp-input", title: "CSP Input", description: "Prevents Content-Security-Policies that look strict but stop nothing by reading the policy the way a browser does: it flags 'unsafe-inline' without a nonce, 'unsafe-eval', * and data: or https: in script-src, a missing default-src, object-src or base-uri, unquoted keywords, a missing semicolon or a stray comma (which splits a header into two policies), allowlisted hosts known to serve JSONP or AngularJS, typo'd or duplicate directives and report-only traps (a Report-Only header pasted as the real one, no report endpoint, a report-only <meta> tag), pins each to its directive in a readout and fixes most in one tap.", category: "Inputs that catch typos", Demo: CspInputDemo },
  { name: "public-env-guard", title: "Public Env Guard", description: "Stops secrets shipping in the client bundle by reading a .env the way the bundler does, listing every NEXT_PUBLIC_, VITE_, REACT_APP_, EXPO_PUBLIC_ or PUBLIC_ variable that reaches the browser, flagging secret key shapes, Supabase service_role JWTs, passwords in URLs, secret names and high-entropy values (while letting publishable keys through), and renaming a key to server-only in one tap with a reminder to rotate it.", category: "Inputs that catch typos", Demo: PublicEnvGuardDemo },
  { name: "robots-txt-guard", title: "Robots.txt Guard", description: "Stops a robots.txt from quietly de-indexing a site by flagging Disallow: / headed for production, staging leftovers, rules that block the CSS and JS Google renders with (tested against real asset paths), relative or wrong-host sitemaps, directive typos and rules Google ignores, with one-tap fixes and a URL tester that names the line deciding each crawl.", category: "Inputs that catch typos", Demo: RobotsTxtGuardDemo },
  { name: "image-tag-input", title: "Image Tag Input", description: "Stops deploys from pulling the wrong container by reading the reference back the way Docker resolves it (implied docker.io/library/ and :latest shown), flagging :latest or no tag in production, tags that move, typo'd or frozen registries, private images that fall back to Docker Hub, malformed digests and arch-specific tags that won't run on the target, with one-tap fixes including pinning a digest.", category: "Inputs that catch typos", Demo: ImageTagInputDemo },
  { name: "invoice-number-check", title: "Invoice Number Check", description: "Keeps GST invoice numbers legal under CGST Rule 46(b) by counting to 16, naming the character that isn't a letter, digit, - or /, catching a number already used this financial year even in different capitals (as GST portals compare them), a stale year token, a skipped or reused counter and gaps in the series, and offering the next number with a fresh series from 1 April.", category: "Inputs that catch typos", Demo: InvoiceNumberCheckDemo },
  { name: "ctc-breakdown-input", title: "CTC Breakdown Input", description: "Stops a job offer's headline CTC being mistaken for pay by splitting it into fixed pay, variable, ESOPs, joining bonus, gratuity and PF, estimating gratuity and PF in one tap, working out monthly in-hand pay with every assumption written down, and flagging offers where in-hand is far below the headline.", category: "Inputs that catch typos", Demo: CtcBreakdownInputDemo },
  { name: "column-mapper", title: "Column Mapper", description: "Stops a spreadsheet landing in the wrong fields by checking a column mapping against the values themselves: emails sitting in the phone column, first and last names swapped, DD/MM read as MM/DD (with a readback of what a date becomes), the same field picked twice and required fields left unmapped, each with a one-tap fix.", category: "Inputs that catch typos", Demo: ColumnMapperDemo },
  { name: "guest-count-picker", title: "Guest Count Picker", description: "Prevents bookings a hotel will bounce by asking each child's age and catching a child over the age limit (or young enough to be a free infant), infants with no adult, rooms over capacity or out of cots, and a room split that doesn't add up to the party, each with a one-tap fix.", category: "Inputs that catch typos", Demo: GuestCountPickerDemo },
  { name: "pin-drop-check", title: "Pin Drop Check", description: "Prevents deliveries to the wrong door by measuring a dropped map pin against the typed address and PIN area (ignoring gaps inside GPS accuracy), flagging pins in water or on a highway from your geo helper, drawing the gap on a to-scale SVG sketch with no map library, and asking \"Use pin or address?\".", category: "Inputs that catch typos", Demo: PinDropCheckDemo },
  { name: "boolean-query-input", title: "Boolean Query Input", description: "Prevents boolean searches that quietly return the wrong people by showing how the engine will group AND and OR (with the brackets it implies highlighted) and offering the grouping you meant, and by catching unclosed quotes and brackets, curly quotes, [ ] used as brackets, lowercase and/or searched as words and dangling operators, each with a one-tap fix.", category: "Inputs that catch typos", Demo: BooleanQueryInputDemo },
  { name: "salary-input", title: "Salary Input", description: "Prevents mis-stated salaries by catching a monthly figure entered as yearly (and back), a bare \"12\" meant as 12 LPA and an extra zero against the role's range, reading every amount back in lakh/crore, per month and per year, and offering a one-tap fix for each.", category: "Inputs that catch typos", Demo: SalaryInputDemo },
  { name: "pincode-input", title: "PIN Code Input", description: "Prevents parcels going to the wrong place by reading the state from an Indian PIN's first digits as you type (offline) and flagging a mismatch with the picked state, catching O typed for 0, wrong lengths, unused prefixes, Army Post codes and ZIP or UK postcodes typed for India, then reading the area back from a pluggable lookup and checking the city, with one-tap fixes.", category: "Inputs that catch typos", Demo: PincodeInputDemo },
  { name: "password-hint-guard", title: "Password Hint Guard", description: "Prevents password hints and security answers that give the password away (the flaw that exposed millions of Adobe passwords in 2013) by spotting the password inside them, also backwards, spaced out or in leetspeak, a large piece of it, or a 'same as my bank' reuse admission, without ever displaying the password, and removing the leak in one tap.", category: "Inputs that catch typos", Demo: PasswordHintGuardDemo },
  { name: "cors-origin-input", title: "CORS Origin Input", description: "Prevents CORS allow-lists that silently never match or expose the API to every site by catching * with credentials, null, a trailing slash or path, a missing scheme, a default port and http or localhost in production, with one-tap fixes and a tester that names the near miss blocking an origin.", category: "Inputs that catch typos", Demo: CorsOriginInputDemo },
  { name: "webhook-url-input", title: "Webhook URL Input", description: "Stops a webhook from being pointed somewhere events can't arrive by judging the URL for the environment it's saved to (an ngrok, tunnel, localhost or private-IP URL is an error in production but a hint in test mode, a staging host is flagged, plain http and a missing path get a fix) and diffing it against the last saved URL, warning when only a www or trailing slash changed because senders treat the resulting redirect as a failure, with a one-tap revert.", category: "Inputs that catch typos", Demo: WebhookUrlInputDemo },
  { name: "coupon-input", title: "Coupon Input", description: "Stops shoppers giving up on a code that should work by cleaning pasted spaces, hidden characters and case, catching O-vs-0 style look-alikes with a one-tap fix, saying exactly why a code didn't apply (cart minimum with the gap, expiry date, excluded items, already used), showing the real saving and any cap, and asking before a worse code replaces a better one.", category: "Inputs that catch typos", Demo: CouponInputDemo },
  { name: "size-fit-picker", title: "Size Fit Picker", description: "Prevents wrong-size orders by converting UK, US, EU and IN sizes live without losing the pick, reading back the shopper's usual size adjusted for brands that run small or large, and catching their usual number clicked in the wrong system (US 8 is a UK 7) with a one-tap fix.", category: "Inputs that catch typos", Demo: SizeFitPickerDemo },
  { name: "paste-target-guard", title: "Paste Target Guard", description: "Prevents payments to a clipboard-hijacked IBAN, UPI ID or wallet address by comparing what lands in the field with what was copied on the page or entered earlier, and flagging look-alikes of saved recipients, then showing both side by side in groups (start and end first, differing characters marked, \"ends match\" called out because modern clippers copy them) with the original one tap away.", category: "Inputs that catch typos", Demo: PasteTargetGuardDemo },
  { name: "email-input", title: "Email Input", description: "Prevents bounced sign-ups from typo'd addresses by spotting misspelled domains like gmial.con or rediffmial.com with Damerau-Levenshtein matching and offering a one-tap, never automatic, fix, and offers matching providers while the domain is still being typed so the typo never happens.", category: "Inputs that catch typos", Demo: EmailInputDemo },
  { name: "password-input", title: "Password Input", description: "Prevents 'wrong password' lockouts that were really Caps Lock, a non-Latin keyboard layout or a pasted trailing space, by warning about each one as it happens.", category: "Inputs that catch typos", Demo: PasswordInputDemo },
  { name: "match-field", title: "Match Field", description: "Prevents mistyped passwords and bank account numbers by showing exactly which character the confirmation stops matching at, without revealing either value, and by refusing a paste into the confirm box only when it is a copy of the first entry, so password managers keep working.", category: "Inputs that catch typos", Demo: MatchFieldDemo },
  { name: "amount-input", title: "Amount Input", description: "Prevents paying ten times too much (or too little) by grouping digits live (lakh/crore aware), spelling the amount out like a cheque, and flagging an extra or missing zero against the usual amount with a one-tap fix.", category: "Inputs that catch typos", Demo: AmountInputDemo },
  { name: "date-sanity-input", title: "Date Sanity Input", description: "Prevents wrong-date bookings by reading the weekday back and catching year typos, past or future dates on the wrong side of today, and weekends, each with a one-tap fix.", category: "Inputs that catch typos", Demo: DateSanityInputDemo },
  { name: "clean-paste-input", title: "Clean Paste Input", description: "Prevents 'identical' codes and IDs from failing by stripping invisible zero-width, BOM, soft-hyphen and bidi characters on paste with an undo, and flagging any that arrive another way with a one-tap fix.", category: "Inputs that catch typos", Demo: CleanPasteInputDemo },
  { name: "otp-paste-input", title: "OTP Paste Input", description: "Prevents failed verifications by pulling the right one-time code out of a whole pasted SMS or email while ignoring phone numbers, amounts and order numbers, and accepting digits typed or pasted in any script (full-width, Devanagari, Arabic-Indic).", category: "Inputs that catch typos", Demo: OtpPasteInputDemo },
  { name: "url-input", title: "URL Input", description: "Prevents broken, insecure and disguised links by adding a missing https://, flagging http, Cyrillic or Greek lookalike hostnames and a “paypal.com@” login prefix that hides the real site, fixing typo'd endings like .con, cleaning the words and full stop a copied sentence leaves behind, and stripping tracking parameters in one tap.", category: "Inputs that catch typos", Demo: UrlInputDemo },
  { name: "phone-input", title: "Phone Input", description: "Prevents saving unreachable numbers by cleaning pasted input (separators, a leading 0, a doubled +91 or 0091), switching country from the dial code and area code (+1 416 is Canada, +1 876 Jamaica), warning on the wrong digit count, checking the digits against Google's libphonenumber ranges and line types (a landline or premium-rate number in an OTP field), and reading back the exact E.164 value.", category: "Inputs that catch typos", Demo: PhoneInputDemo },
  { name: "char-budget", title: "Character Budget", description: "Prevents posts that get cut off and SMS that silently cost double by counting graphemes against X, SMS, LinkedIn and meta-description limits at once, and naming the curly quote or emoji that forced UCS-2.", category: "Inputs that catch typos", Demo: CharBudgetDemo },
  { name: "code-input", title: "Code Input", description: "Prevents commands, JSON and keys that fail for invisible reasons by disabling autocorrect and catching smart quotes, dashes, ellipses and hidden characters by line and column, with a one-tap fix and optional JSON validation.", category: "Inputs that catch typos", Demo: CodeInputDemo },
  { name: "unit-input", title: "Unit Input", description: "Prevents values stored in the wrong unit by noticing when a number is far more plausible in another one (70 cm is probably inches, 98.6 °C is °F) or is typed as 5'9\", and offering a one-tap conversion at the right precision or a unit switch.", category: "Inputs that catch typos", Demo: UnitInputDemo },
  { name: "time-confirm", title: "Time Confirm", description: "Prevents meetings booked 12 hours or a day off by asking AM or PM when a time is ambiguous, spelling out noon and midnight, catching times a DST change skips (with a one-tap move to the real time) or repeats (with a choice of which one), and showing the moment in other time zones with day-shift flags.", category: "Inputs that catch typos", Demo: TimeConfirmDemo },
  { name: "quantity-stepper", title: "Quantity Stepper", description: "Prevents accidental bulk orders by clamping to min, max and stock with an explanation, holding big typed jumps for a \"Did you mean 10?\" confirmation, ignoring the scroll wheel and accelerating on long-press.", category: "Inputs that catch typos", Demo: QuantityStepperDemo },
  { name: "inline-edit", title: "Inline Edit", description: "Prevents lost and clobbered edits in click-to-edit text: a cancelled edit can be restored, a failed save keeps your draft, and a value changed by someone else mid-edit is flagged instead of silently overwritten (clicking away then keeps the editor open rather than saving over it).", category: "Inputs that catch typos", Demo: InlineEditDemo },
  { name: "checksum-input", title: "Checksum Input", description: "Prevents payments and orders going to a mistyped IBAN, card, ISBN or IFSC by checking mod-97, Luhn and ISBN check digits and country lengths as you type, then highlighting the one swapped or doubled character that explains a failure instead of guessing a digit.", category: "Inputs that catch typos", Demo: ChecksumInputDemo },
  { name: "name-input", title: "Name Input", description: "Prevents shouty, mangled or swapped names on records by spotting caps lock, all-lowercase, stray digits, doubled spaces and a first/last mix-up, and offering, never forcing, a fix cased the way McDonald, O'Brien, van der Berg and de la Cruz are really written.", category: "Inputs that catch typos", Demo: NameInputDemo },
  { name: "percent-input", title: "Percent Input", description: "Prevents 100× rate mistakes by catching 0.15 typed for 15%, 0.25 basis points for 25, and 150% where 100% is the cap, reading the result back in plain money (15% of ₹2,000 = ₹300) and offering a one-tap fix.", category: "Inputs that catch typos", Demo: PercentInputDemo },
  { name: "range-pair", title: "Range Pair", description: "Prevents filters and bookings built on a backwards, empty or wildly oversized range by catching reversed ends (moving a 28 Dec → 3 Jan end into next year instead of just swapping), equal exclusive ends and year or extra-zero typos, each with a one-tap fix.", category: "Inputs that catch typos", Demo: RangePairDemo },
  { name: "schedule-readback", title: "Schedule Readback", description: "Prevents shipping a cron job that fires at the wrong time by reading the expression back in plain English, listing the next runs in your own time zone beside the server's, and catching classics like every-minute stars, day-of-month OR day-of-week, the 31st skipping months and 30 February, with one-tap fixes.", category: "Inputs that catch typos", Demo: ScheduleReadbackDemo },
  { name: "near-duplicate-input", title: "Near-Duplicate Input", description: "Prevents a second \"Marketing\" tag by spotting near-duplicates as you type (capitals, spacing, punctuation, plurals, one-letter typos, but never different numbers like Q3 vs Q4) and offering Use existing, which is also what Enter does.", category: "Inputs that catch typos", Demo: NearDuplicateInputDemo },
  { name: "list-paste", title: "List Paste", description: "Prevents importing or inviting a messy pasted list by splitting it on lines, commas, semicolons and tabs (keeping \"Shah, Priya\" <…> whole), counting valid, duplicate and invalid items with the line and reason for each, and removing the bad ones in one undoable tap, with a pluggable validator.", category: "Inputs that catch typos", Demo: ListPasteDemo },
  { name: "slug-input", title: "Slug Input", description: "Prevents broken and colliding URLs: the slug follows the title with proper transliteration (Straße → strasse) until published, reads back the full URL, checks for collisions as you type with the next free slug one tap away, and warns that editing a live slug breaks links, keeping a redirect by default.", category: "Inputs that catch typos", Demo: SlugInputDemo },
  { name: "env-paste", title: "Env Paste", description: "Catches the .env slips loaders accept silently (stray or curly quotes, padded values, a ' #' that cuts a value short, duplicate keys, bad key names, empty values, test keys in production) by showing a parsed table of what the app will actually read, with one-tap fixes.", category: "Inputs that catch typos", Demo: EnvPasteDemo },
  { name: "split-allocator", title: "Split Allocator", description: "Prevents splits that add up to 99%, 101% or leave someone on 0 by showing what's left as you type, giving the rest to any row in one tap, and rounding every automatic split with largest remainder so it sums to the total exactly.", category: "Inputs that catch typos", Demo: SplitAllocatorDemo },
  { name: "homoglyph-guard", title: "Homoglyph Guard", description: "Stops spoofed usernames and domains like pаypal.com (Cyrillic а) by detecting look-alike, mixed-script, styled and zero-width characters with UTS #39-style rules, naming each one's real script and code point, and offering the plain-ASCII version in one tap.", category: "Inputs that catch typos", Demo: HomoglyphGuardDemo },
  { name: "json-field", title: "JSON Field", description: "Stops broken JSON from being saved by validating as you type, pointing a caret at the exact line and column, and repairing trailing commas, single or smart quotes, unquoted keys, comments, Python literals, missing commas and unclosed braces in one token-aware tap.", category: "Inputs that catch typos", Demo: JsonFieldDemo },
  { name: "regex-field", title: "Regex Field", description: "Catches regexes that look right but aren't (an unescaped dot, a missing ^…$ that lets \"abc123x\" pass, a greedy .*, catastrophic backtracking like (a+)+) with plain-English hints, one-tap fixes and live-highlighted test strings matched in a time-capped Web Worker that can't freeze the page.", category: "Inputs that catch typos", Demo: RegexFieldDemo },
  { name: "contrast-picker", title: "Contrast Picker", description: "Stops unreadable text colours from shipping by showing the WCAG 2 contrast ratio truncated, never rounded up (#777 on white is 4.47:1 and fails), with AA/AAA marks for normal and large text and a one-tap nearest passing colour that moves only lightness so the hue stays on brand.", category: "Inputs that catch typos", Demo: ContrastPickerDemo },
  { name: "address-check", title: "Address Check", description: "Prevents returned parcels by catching a missing flat or house number, a postcode that doesn't fit the country (or fits another one), a city the postcode lookup places elsewhere, and PO boxes couriers can't reach, with one-tap fixes and a live readback of the printed label.", category: "Inputs that catch typos", Demo: AddressCheckDemo },
  { name: "tax-id-input", title: "Tax ID Input", description: "Prevents invoices going out with a mistyped GSTIN, PAN or EU VAT number by recomputing the GSTIN's mod-36 check character, reading back the state, holder type and country, and pinpointing the exact wrong character with a one-tap fix for look-alikes, swaps and GR instead of EL.", category: "Inputs that catch typos", Demo: TaxIdInputDemo },
  { name: "duration-input", title: "Duration Input", description: "Prevents wrong timesheet and estimate entries by parsing 1h30, 90m, 1.5h, 1:30 and 2d 4h into one duration read back in words, catching 1.50 typed for 1 h 50 min and asking whether 1:30 is h:mm or m:ss when the limits can't decide.", category: "Inputs that catch typos", Demo: DurationInputDemo },
  { name: "filename-input", title: "Filename Input", description: "Prevents broken renames by selecting only the base name on focus, warning with a one-tap undo when the extension changes or disappears, and catching illegal characters, Windows reserved names like CON or NUL.txt, trailing dots and spaces, over-long names and duplicates that differ only in capitals.", category: "Inputs that catch typos", Demo: FilenameInputDemo },
  { name: "coordinate-input", title: "Coordinate Input", description: "Prevents pins on the wrong continent by reading decimal, DMS and pasted map links (taking Google's pin, not the map centre), catching swapped latitude and longitude, flipped west or south signs against an expected area and 0, 0 defaults, and reading every point back with an OpenStreetMap link.", category: "Inputs that catch typos", Demo: CoordinateInputDemo },
  { name: "cidr-input", title: "CIDR Input", description: "Prevents misconfigured firewall rules and subnets by reading an IPv4 or IPv6 CIDR back as its exact range and address count, catching host bits set (with both the network and single-host readings as one-tap fixes), and warning on 0.0.0.0/0 and on overlaps with existing ranges.", category: "Inputs that catch typos", Demo: CidrInputDemo },
  { name: "version-range-input", title: "Version Range Input", description: "Prevents dependency ranges that don't mean what you think by reading npm-style semver ranges back in plain English, marking which published versions match and which one installs, and warning about ^0.x lock-in, a hyphen with no spaces, commas for AND and ranges that match nothing.", category: "Inputs that catch typos", Demo: VersionRangeInputDemo },
  { name: "zero-result-rescue", title: "Zero Result Rescue", description: "Prevents users giving up on an empty search by explaining what got in the way and offering only fixes proven to return results: a did-you-mean from your own vocabulary, the query retyped in the right keyboard layout or without Caps Lock, dropping the filter that hides everything, or searching all categories, each with its result count, counted in memory or by async count-only API calls.", category: "Inputs that catch typos", Demo: ZeroResultRescueDemo },
  { name: "mixed-value-field", title: "Mixed Value Field", description: "Prevents bulk edits from silently overwriting records by showing \"Mixed (3 values)\" with the distribution instead of a blank or the first record's value, leaving each record alone unless you pick a value, and reading back exactly what saving changes, counting only the records that actually change.", category: "Inputs that catch typos", Demo: MixedValueFieldDemo },
  { name: "card-expiry-input", title: "Card Expiry Input", description: "Prevents declined payments from mistyped card expiries by masking MM/YY, reading the date back as valid through the month's last day, and catching month 13, the year typed first, a four-digit year, an expired card and one that runs out before the next renewal, with one-tap fixes.", category: "Inputs that catch typos", Demo: CardExpiryInputDemo },
  { name: "username-input", title: "Username Input", description: "Prevents impersonation and lost handles by reading back the exact handle that gets registered, blocking reserved words even in disguise (adm1n) and case-only duplicates, flagging look-alikes of existing names with a UTS #39-style skeleton, and checking availability after a pause with free alternatives to tap.", category: "Inputs that catch typos", Demo: UsernameInputDemo },
  { name: "billing-period-input", title: "Billing Period Input", description: "Prevents mispriced plans by reading a recurring price back in every period (₹499/month = ₹5,988/year) and, against a reference price, catching a yearly price typed into the monthly field, a team total entered per seat and other implausible jumps, each with a one-tap fix.", category: "Inputs that catch typos", Demo: BillingPeriodInputDemo },
  { name: "glob-input", title: "Glob Input", description: "Prevents config globs that silently miss or swallow files by running the pattern live against the real file list, flagging no-match and match-everything patterns, the * vs ** mix-up that skips subfolders, ** glued to a name, ./ and backslashes, with one-tap fixes and a dependency-free matcher.", category: "Inputs that catch typos", Demo: GlobInputDemo },
  { name: "replace-preview", title: "Replace Preview", description: "Stops replace-all from mangling text (\"cat\" → \"dog\" turning \"category\" into \"dogegory\") by previewing every match in context with a count, naming the matches that sit inside longer words with a one-tap whole-word fix, preserving case, letting you skip single matches and undo the replace.", category: "Inputs that catch typos", Demo: ReplacePreviewDemo },
  { name: "i18n-string-field", title: "i18n String Field", description: "Stops broken translations shipping by checking each one against its source as it is typed: dropped or renamed placeholders ({count}, %s, {{name}}, <b>…</b>), unclosed tags, ICU plural forms the target language needs per CLDR, rendered length against the UI budget and source text pasted back untranslated, with one-tap fixes.", category: "Inputs that catch typos", Demo: I18nStringFieldDemo },
  { name: "sql-guard", title: "SQL Guard", description: "Stops a forgotten WHERE from wiping a table: a small tokenizer (comments and strings don't count) flags UPDATE/DELETE without WHERE, a WHERE hidden in a comment, always-true conditions like WHERE 1=1, DROP and TRUNCATE as you type, asks before any write on production, shows estimated affected rows from a pluggable function, and requires typing the table name before a destructive run.", category: "Inputs that catch typos", Demo: SqlGuardDemo },
  { name: "ifsc-input", title: "IFSC Input", description: "Prevents bank transfers to the wrong branch by catching the letter O typed for the IFSC's fixed zero, a missing 0, digits in the bank code and guessed prefixes like AXIS for UTIB, then reading the branch back from a pluggable lookup (Razorpay IFSC API shape) and warning when it belongs to a different bank than the one picked.", category: "Inputs that catch typos", Demo: IfscInputDemo },
  { name: "upi-id-input", title: "UPI ID Input", description: "Prevents UPI payments to a typo'd or wrong VPA by cleaning pasted upi://pay links, catching emails, typo'd handles (@okaxsi), app names typed as handles (@gpay), wrong-length or +91 phone IDs and the retired @paytm, then reading back the registered name from a pluggable check and flagging when it differs from the expected name or the name the link claimed, with every message overridable for translation.", category: "Inputs that catch typos", Demo: UpiIdInputDemo },
  { name: "shift-time-input", title: "Shift Time Input", description: "Prevents wrong timesheets and rosters by reading 22:00–06:00 as an 8 h shift that ends the next day, asking whether 9:00–5:00 meant 5 PM (and whether 10–6 is a day or a night shift) instead of logging 20 h, questioning 0 h, over-long and 26:00-style entries, and deducting the break while catching one typed in hours, and, given the day and time zone, counts the real hours when the clocks change mid-shift (a 22:00–06:00 night is 9 h when they fall back).", category: "Inputs that catch typos", Demo: ShiftTimeInputDemo },
  { name: "dimension-input", title: "Dimension Input", description: "Prevents wrong sizes on listings, shipments and orders by labelling each side, filling all three from a pasted \"16 x 12 x 8 in\", and checking them against what is being measured to catch the wrong unit, a side with an extra digit and sides entered in the wrong order, then reading the size back in metric and imperial with volume and courier volumetric weight.", category: "Inputs that catch typos", Demo: DimensionInputDemo },
  { name: "markdown-check", title: "Markdown Check", description: "Catches Markdown that will render differently from how it reads (an unclosed ** or backtick, [text] (url) with a space, empty or space-broken links, #Title with no space, raw HTML the sanitizer strips) and previews each spot the way it will actually render, with a one-tap fix.", category: "Inputs that catch typos", Demo: MarkdownCheckDemo },
  { name: "yaml-field", title: "YAML Field", description: "Catches YAML that loads without an error but means something else (NO, yes, on and off read as booleans, 1.10 read as 1.1, 0755 as octal, 22:22 as base-60, duplicate keys, tabs and misaligned indentation) by showing each one's line, column and what the parser will really read, with one-tap quoting and alignment fixes.", category: "Inputs that catch typos", Demo: YamlFieldDemo },
  { name: "shortcut-recorder", title: "Shortcut Recorder", description: "Stops users saving a keyboard shortcut that will never fire or will clobber something, by checking what they press against browser and OS reserved keys on every platform (Ctrl+W, ⌘Q, Ctrl+T), the app's own bindings and layouts where the key needs AltGr, then reading it back as ⌘ on Mac and Ctrl on Windows/Linux.", category: "Inputs that catch typos", Demo: ShortcutRecorderDemo },
  { name: "webhook-test", title: "Webhook Test", description: "Stops a webhook from being saved to a URL the sender can't deliver to, by flagging localhost and private IPs, plain http, a missing path and tunnel URLs, then judging a pluggable test delivery the way the sender will: redirects fail (with a one-tap switch to the final URL), slow replies near the timeout and 200 login pages are caught.", category: "Inputs that catch typos", Demo: WebhookTestDemo },
  { name: "hashtag-input", title: "Hashtag Input", description: "Catches hashtags that quietly fail (a space or apostrophe that cuts the tag short, case-only duplicates, all-digit or banned tags, posts over a platform's limit) and suggests CamelCase like #OpenSource so screen readers say the words, each with a one-tap fix.", category: "Inputs that catch typos", Demo: HashtagInputDemo },
  { name: "tax-inclusive-input", title: "Tax-Inclusive Input", description: "Stops tax being added twice by making 'includes / excludes GST' an explicit toggle, reading back net + tax = gross, and flagging an 'excludes' price that divides back to a round number, a mode switch that silently changed the total, or a typo'd rate like 0.18 or 180.", category: "Inputs that catch typos", Demo: TaxInclusiveInputDemo },
  { name: "timezone-picker", title: "Timezone Picker", description: "Prevents scheduling in the wrong zone: search by city, country or abbreviation, with ambiguous ones like IST or PST listing every meaning instead of guessing, each result showing local time and UTC offset, plus warnings for a clock change in the coming weeks and a zone that differs from the device's.", category: "Inputs that catch typos", Demo: TimezonePickerDemo },
  { name: "scope-picker", title: "Scope Picker", description: "Stops over-privileged API keys by reading back in plain words what the key can do (destructive powers in red), flagging write, delete and admin scopes, offering 'Only what you've used' from real usage, and warning when the key never expires.", category: "Inputs that catch typos", Demo: ScopePickerDemo },
  { name: "brand-color-input", title: "Brand Color Input", description: "Stops near-miss brand colours from shipping by naming the closest palette token with a perceptual (OKLab) distance and offering a one-tap snap when a value is a hair off (#1e40ae vs #1e40af), and by catching pasted junk, the letter O for zero, a digit too many or few, alpha hidden in 4- and 8-digit hex, and Android #AARRGGBB order that CSS renders as a different colour.", category: "Inputs that catch typos", Demo: BrandColorInputDemo },
  { name: "version-bump", title: "Version Bump", description: "Stops breaking changes shipping as a minor or patch that every ^range installs automatically by reading the changes (Conventional Commits or tagged), marking the bump they need, previewing each option's version, warning when the pick is too small (or a needless major), and reading back \"1.4.2 → 2.0.0\" with who gets it, while handling 0.x's shifted breaking slot, pre-release tags that drop on release, and tags that sort backwards (2.0.0-beta.0 < 2.0.0-rc.1).", category: "Inputs that catch typos", Demo: VersionBumpDemo },
  { name: "dose-input", title: "Dose Input", description: "Prevents ten-fold medication errors by flagging the ISMP error-prone dose designations as they're typed (trailing zeros like 1.0 mg read as 10 mg, a missing leading zero, U and IU, µg, cc, a unit flush against the number, uncommaed big numbers), rewriting the dose safely in one tap, offering the likely meant value when a dose is 10× outside the drug's usual range (mg typed for mcg, a slipped decimal), and spelling it back in words.", category: "Inputs that catch typos", Demo: DoseInputDemo },
  { name: "wrong-layout-input", title: "Wrong Layout Input", description: "Catches text typed with the wrong keyboard layout (\"ghbdtn\" meant \"привет\", \"руддщ\" meant \"hello\", plus Hebrew, Greek and Hindi InScript) by scoring it against letter-pair models of each language and spellings no real word has, then offers the retyped text as a one-tap fix with undo, leaving names, acronyms, links and code alone.", category: "Inputs that catch typos", Demo: WrongLayoutInputDemo },
  { name: "utm-check", title: "UTM Check", description: "Stops campaign links that fragment analytics by catching, as the URL is built or pasted, mixed case and spaces (Facebook vs facebook, \"Diwali Sale\" vs diwali_sale, or a value your reports already spell differently), source and medium swapped, a medium GA4's default channel rules file as organic or Unassigned, misspelled keys, a second \"?\", tags after \"#\" and tags on links back to your own site, reading back the GA4 channel and fixing each in one tap or all at once.", category: "Inputs that catch typos", Demo: UtmCheckDemo },
  { name: "reorder-readback", title: "Reorder Readback", description: "Stops a slipped drag from silently reordering priorities, fallbacks or steps by reading every drop back with its consequence (\"Moved Razorpay from 3rd to 1st. It's now tried first.\") with Undo, dragging only from the grip so touch scrolling never reorders, refusing to push pinned rows aside with a reason, marking rows moved since the last save, and meeting WCAG 2.2 2.5.7 with click-and-arrow moves plus Space/arrow/Escape keyboard moves with debounced announcements.", category: "Forms and saving", Demo: ReorderReadbackDemo },
  { name: "nominee-check", title: "Nominee Check", description: "Stops a bank, locker or demat nomination that won't do what the holder thinks, by checking it against the 2025 bank nomination rules and SEBI's 2026 limits: shares that don't add to 100%, a fifth bank nominee (or fourth demat one) that won't count, a split on a locker that can only go in order, a demat nominee with no relationship or a minor with no date of birth, a minor with no adult to receive, the same person twice and no nominee at all, then reading back in plain words who gets what, with one-tap fixes.", category: "Forms and saving", Demo: NomineeCheckDemo },
  { name: "passport-validity-check", title: "Passport Validity Check", description: "Stops travellers booking a trip their passport can't make by checking it against the destination's rule (the 6-month rule, Schengen's 3 months after you leave and 10 years since issue, blank pages), naming the exact date it must last until and offering the latest return date that would pass, with sourced default rules you can replace.", category: "Forms and saving", Demo: PassportValidityCheckDemo },
  { name: "seat-gap-check", title: "Seat Gap Check", description: "Stops groups checking out with seats they'll regret by catching a party split across the row, a single empty seat left behind (which many cinemas and theatres refuse) and a child seated away from every adult, marking the problem seats and moving everyone to the nearest block that fits, children beside adults, in one tap.", category: "Forms and saving", Demo: SeatGapCheckDemo },
  { name: "formula-overwrite-guard", title: "Formula Overwrite Guard", description: "Stops a spreadsheet paste from silently wiping formulas, locked cells or the heading row, or spilling data past the table edge, by previewing in place which cells would change and how, leaving out a heading row the copy dragged along, and offering to paste values only into the empty and non-formula cells, while safe pastes go straight in with Undo.", category: "Forms and saving", Demo: FormulaOverwriteGuardDemo },
  { name: "passkey-name-prompt", title: "Passkey Name Prompt", description: "Prevents a security page full of identical \"Passkey\" rows nobody can tell apart (or safely delete) by prefilling a distinct name right after creation, from the AAGUID for syncing managers like iCloud Keychain or 1Password and from the device for the rest (\"Mac · Chrome\", or a phone or security key when it was made off this device), numbering it when taken, blocking empty and duplicate names with a one-tap fix, nudging away from generic ones, and saying whether the passkey syncs or lives on this device only.", category: "Forms and saving", Demo: PasskeyNamePromptDemo },
  { name: "irreversible-diff-badge", title: "Irreversible Diff Badge", description: "Stops people saving a change they can't take back by marking permanent fields with a chip that turns amber once edited and, before save, listing only the permanent fields that actually changed as a from → to readback with consequences and one-tap Revert, behind a confirmation that resets whenever that list changes.", category: "Forms and saving", Demo: IrreversibleDiffBadgeDemo },
  { name: "stale-attachment-check", title: "Stale Attachment Check", description: "Prevents sending an old copy by checking each attachment against the files beside it (a newer save of the same file, report_v3_final.pdf edited today next to the attached report_v2.pdf), names that say draft, old, copy or (1), Office lock files and a file dated before the subject's date, with a one-tap swap to the newer file and Undo.", category: "Forms and saving", Demo: StaleAttachmentCheckDemo },
  { name: "dependency-license-check", title: "Dependency License Check", description: "Prevents adding a dependency your project isn't allowed to use by reading each SPDX expression against your policy (GPL or AGPL in closed-source code, no or unrecognised license, source-available terms in a hosted product, deny lists) and catching relicenses between versions with a one-tap \"Stay on\" the last version under the old license, while dual licenses and dev-only copyleft pass quietly.", category: "Forms and saving", Demo: DependencyLicenseCheckDemo },
  { name: "heading-outline", title: "Heading Outline", description: "Prevents a heading structure screen reader users can't navigate by showing the live outline of a Markdown draft or any DOM region and flagging skipped levels (drawn as dashed ghost rows), extra or missing H1s, empty headings, bold text posing as a heading and paragraph-length headings, with a one-tap \"Make it H3\" fix and rows that jump to the heading.", category: "Forms and saving", Demo: HeadingOutlineDemo },
  { name: "link-text-check", title: "Link Text Check", description: "Prevents links that fail screen reader users browsing a links list by flagging \"click here\" and \"read more\", URLs as link text, empty links and the same text pointing to different places, with a one-tap rewrite that lifts the sentence's own words into the link (\"To see the venue map, click here\" → \"See the venue map\") and a view of the links list as it will be read out.", category: "Forms and saving", Demo: LinkTextCheckDemo },
  { name: "reading-level", title: "Reading Level", description: "Prevents writing that's too hard for its readers with a live Flesch-Kincaid grade against a target, the hardest sentences tinted in place (only when long and dense, so plain long sentences aren't nagged) with the reason and a jump to each, and one-tap plain-word swaps (\"utilize\" → \"use\", \"in the event that\" → \"if\").", category: "Forms and saving", Demo: ReadingLevelDemo },
  { name: "backup-codes", title: "Backup Codes", description: "Stops users locking themselves out with recovery codes they never kept: Continue unlocks only after the codes are downloaded, printed or copied (or all three with require=\"all\"), then one code must be typed back (paste refused, look-alike characters forgiven) to prove the saved copy is readable.", category: "Forms and saving", Demo: BackupCodesDemo },
  { name: "recovery-check", title: "Recovery Check", description: "Prevents account lockouts by asking \"could you get back in if you lost your phone?\": it flags recovery email or phone nobody has confirmed in months, no backup method, a password-only account and one phone acting as both second factor and recovery, each with a one-tap fix.", category: "Forms and saving", Demo: RecoveryCheckDemo },
  { name: "unsaved-changes-bar", title: "Unsaved Changes Bar", description: "Stops people leaving with edits they think were saved by naming every dirty field, guarding the tab close, saving on Ctrl/⌘+S and asking twice before Discard.", category: "Forms and saving", Demo: UnsavedChangesBarDemo },
  { name: "save-status", title: "Save Status", description: "Stops silent autosave failures by showing an aging 'Saved · 2 min ago', an honest offline state and a Retry on error, backed by a debounced hook that never saves stale data out of order.", category: "Forms and saving", Demo: SaveStatusDemo },
  { name: "error-summary", title: "Error Summary", description: "Prevents users from missing form errors with a GOV.UK-style summary that takes focus on submit, links each error to its field, and ticks items off live as they are fixed, plus a useFormErrors() hook.", category: "Forms and saving", Demo: ErrorSummaryDemo },
  { name: "form-progress", title: "Form Progress", description: "Prevents the \"why won't it submit?\" hunt by counting the required fields still empty or invalid and jumping focus to the next one with a Next missing button.", category: "Forms and saving", Demo: FormProgressDemo },
  { name: "preflight-checklist", title: "Preflight Checklist", description: "Prevents shipping something broken by locking the action until auto and manual checks pass, naming the blockers, resetting ticks when the revision changes and re-verifying right before it runs.", category: "Forms and saving", Demo: PreflightChecklistDemo },
  { name: "attachment-nudge", title: "Attachment Nudge", description: "Prevents the \"see attached\" message with nothing attached by spotting attachment phrases (English, Hindi and Hinglish, ignoring quoted replies, negations and shared cloud links) and asking inline to Attach or Send anyway.", category: "Forms and saving", Demo: AttachmentNudgeDemo },
  { name: "file-guard", title: "File Guard", description: "Stops bad uploads before they start by checking size, type, count, empty files and duplicates, and by reading each file's first bytes to catch a renamed extension, with a one-tap rename fix.", category: "Forms and saving", Demo: FileGuardDemo },
  { name: "draft-restore", title: "Draft Restore", description: "Stops lost form work and stale-draft overwrites by autosaving to localStorage and, on reopen, offering the draft with a field-by-field preview that keeps any value the server changed since, unless you tick it.", category: "Forms and saving", Demo: DraftRestoreDemo },
  { name: "tab-collision", title: "Tab Collision", description: "Stops the same record being edited in two tabs, where the last save silently erases the other, by letting only one tab edit (BroadcastChannel with a storage-event fallback) and making the rest read-only until you choose 'Use this tab'.", category: "Forms and saving", Demo: TabCollisionDemo },
  { name: "review-step", title: "Review Step", description: "Catches wrong or forgotten answers before a multi-step form is sent by listing every answer by step with named Edit links, flagging empty optional fields and values changed since last time, and taking one deliberate submit that ignores carried-over clicks and can't fire twice.", category: "Forms and saving", Demo: ReviewStepDemo },
  { name: "dependent-reset", title: "Dependent Reset", description: "Prevents dependent fields from vanishing silently when a parent changes: a hook clears only what the change made invalid (pruning just the add-ons a new plan lacks), and a notice names each lost value, highlights those fields and offers Undo.", category: "Forms and saving", Demo: DependentResetDemo },
  { name: "version-scrubber", title: "Version Scrubber", description: "Prevents restoring the wrong version by letting you scrub a timeline with the current version pinned, previewing a word diff of exactly what a restore would change, and requiring a second step that counts the words lost and gained and names changed numbers.", category: "Forms and saving", Demo: VersionScrubberDemo },
  { name: "autofill-check", title: "Autofill Check", description: "Catches browser and password-manager autofill putting the wrong value in the wrong field by detecting fills (the :autofill animationstart hook plus a no-typing batch heuristic), outlining and listing them for review, flagging an email in Name or an address that differs from the account with a one-tap fix, and holding the first submit.", category: "Forms and saving", Demo: AutofillCheckDemo },
  { name: "field-history", title: "Field History", description: "Stops people overwriting or misreading a field someone just changed: a trigger beside the label flags a recent change by someone else, opens \"Was ₹500 until Priya changed it yesterday\" with a one-tap revert of that field alone, says what the revert replaces (including your unsaved edit) and lets you undo it.", category: "Forms and saving", Demo: FieldHistoryDemo },
  { name: "terms-changes", title: "Terms Changes", description: "Stops people re-accepting updated terms without seeing what changed: it shows a summary and the exact word diff since the version they accepted, calls out changed numbers, keeps Accept locked until every change has stayed on screen long enough to read (an early tap jumps to the next unread one), and hands back a consent record with both versions and a timestamp.", category: "Forms and saving", Demo: TermsChangesDemo },
  { name: "hidden-field-guard", title: "Hidden Field Guard", description: "Catches values that ride along unseen: when a conditional section is hidden it names the fields that are still filled and whether they'll be submitted or dropped, with Keep, Clear (through real input events, so React state follows) and Undo.", category: "Forms and saving", Demo: HiddenFieldGuardDemo },
  { name: "upload-wait", title: "Upload Wait", description: "Stops a form being sent before its attachments exist: pressing submit mid-upload validates and queues the send, the button fills with combined progress and reads \"Waiting for 2 uploads…\", it submits by itself when they finish, a failed upload pauses it until retried, and leaving mid-upload asks first.", category: "Forms and saving", Demo: UploadWaitDemo },
  { name: "consent-group", title: "Consent Group", description: "Prevents invalid or bundled consent: boxes are never pre-ticked, required terms sit apart from optional purposes, Accept all spells out what it will tick before it does, one plain sentence reads back the choice, and each change yields a record with time, method, text version and a fingerprint of the wording shown.", category: "Forms and saving", Demo: ConsentGroupDemo },
  { name: "dob-input", title: "DOB Input", description: "Prevents wrong birth dates by reading the date and age back as you type and catching this year typed by habit (age 0), future dates, implausible ages, a day typed into the month box, pasted dates that read two ways and under-age sign-ups, with a one-tap fix and the date someone becomes eligible.", category: "Forms and saving", Demo: DobInputDemo },
  { name: "recurrence-scope", title: "Recurrence Scope", description: "Prevents editing more of a recurring series than intended by reading back exactly which dates a This one / This and following / All choice changes, with the count and past ones called out, and warning by date and field before it overwrites occurrences that were edited on their own.", category: "Forms and saving", Demo: RecurrenceScopeDemo },
  { name: "tree-select-readback", title: "Tree Select Readback", description: "Prevents selecting more or less than intended in a nested checkbox tree by reading the choice back in plain words (\"All of Marketing except Paid ads; 3 of 12 in Sales\"), telling a whole-group tick apart from ticking every item, and warning that a whole-group tick also selects items added later, with a one-tap pin to today's items.", category: "Forms and saving", Demo: TreeSelectReadbackDemo },
  { name: "repeat-rows", title: "Repeat Rows", description: "Prevents lost, doubled and junk entries in add-another forms (line items, guests) with min and max limits, Undo in place after a remove, duplicate rows flagged with a one-tap remove, blank rows called out before submit, Enter that adds a row instead of submitting, and focus that lands on the right field.", category: "Forms and saving", Demo: RepeatRowsDemo },
  { name: "step-invalidation", title: "Step Invalidation", description: "Stops an earlier wizard answer from silently breaking later steps: before the change applies it says exactly what goes (\"Changing plan to Basic clears Region on step 3 and removes SSO and Audit log on step 4\"), then marks those steps, walks back through only them and holds Finish until they're checked, and changing the answer back restores what it removed.", category: "Forms and saving", Demo: StepInvalidationDemo },
  { name: "import-preview", title: "Import Preview", description: "Catches a bad spreadsheet import before it lands by finding the real heading row (skipping title lines, flagging headings about to be imported as a record), matching columns by heading and by their values with a confidence, holding the import while a required field is unmapped, and listing every skipped line by its spreadsheet line number and reason (duplicates in the file and against existing records, repeated headings, bad values) before a plain \"Import 412 · skip 7\".", category: "Forms and saving", Demo: ImportPreviewDemo },
  { name: "crop-guard", title: "Crop Guard", description: "Stops a crop that slices a face or headline, or hides it under a platform's UI, by checking pluggable face and text boxes against the crop, the profile circle and Story safe zones, offering a one-tap fit that moves the crop as little as possible, and previewing it at the small size people will actually see.", category: "Forms and saving", Demo: CropGuardDemo },
  { name: "stay-length", title: "Stay Length", description: "Catches off-by-one bookings and leave requests by reading the range back as \"Mon 2 Nov – Sun 8 Nov · 6 nights, 7 days\" and flagging an end before the start, nights confused with days, a check-out that may really be the last night, and weekends or pluggable holidays that change how much leave it costs, each with a one-tap fix.", category: "Forms and saving", Demo: StayLengthDemo },
  { name: "event-overlap", title: "Event Overlap", description: "Stops a calendar event being created or moved onto a clash by listing what it runs into (overlaps, back-to-back with no break, too little travel time between places, busy all-day events, other-zone events read in their own time) on a small timeline, and moving it to the nearest slot that keeps your buffer and travel time in one tap, with Undo.", category: "Forms and saving", Demo: EventOverlapDemo },
  { name: "unanswered-check", title: "Unanswered Check", description: "Stops a test or survey being submitted with questions skipped by accident by listing, before the final submit, the required and optional questions still blank, partly answered ones and those flagged for review as numbered jump links, with time left and how much of it each open question gets, a deliberate second click for blanks, a hard stop for required survey questions and a submit that waits until every answer has saved.", category: "Forms and saving", Demo: UnansweredCheckDemo },
  { name: "cutoff-picker", title: "Cutoff Picker", description: "Stops orders landing on a different day than the shopper thinks by counting down to the store's cutoff in store time with the shopper's own time beside it, naming the holidays and closed days it skips, saying when the store's date isn't the shopper's, and never moving a chosen date silently: when the cutoff passes mid-choice it says the date is gone and offers the new earliest one in one tap.", category: "Forms and saving", Demo: CutoffPickerDemo },
  { name: "trip-date-chain", title: "Trip Date Chain", description: "Stops a hotel being booked for the wrong night by drawing each stay as a bar on a night-by-night strip under the flights, catching a 00:50 landing with the room booked from that date, nights paid before a +1 arrival, gap nights, double-booked nights and a room kept past a 00:35 departure, sliding the stay's bar to the right dates in one tap with Undo, and reading a small-hours departure back as the evening before.", category: "Context and awareness", Demo: TripDateChainDemo },
  { name: "meeting-time-spread", title: "Meeting Time Spread", description: "Stops a recurring meeting always landing in the same person's night by setting the start on a slider with every attendee's own day underneath (night, before work, working, after work, weekend, a day ahead or behind, and DST weeks when the gap shifts, from the tz database), and suggesting the kindest slot: nobody at night first, then the fewest people out of hours, then rotating the pain away from whoever took the last ones (\"Spares Sam, who took the last 3\").", category: "Context and awareness", Demo: MeetingTimeSpreadDemo },
  { name: "bnpl-schedule-check", title: "BNPL Schedule Check", description: "Stops a buy-now-pay-later plan from quietly failing by drawing each payment on a calendar beside other running plans and paydays, flagging a card that expires before a payment, payments due just before payday and plans stacking in the same week, fixing them in one tap (pay from bank, move to payday, with the dots sliding across), showing the late fee and its cap in money, and asking for a second press to confirm while the card problem stands.", category: "Context and awareness", Demo: BnplScheduleCheckDemo },
  { name: "transit-visa-check", title: "Transit Visa Check", description: "Stops travellers booking a layover that needs a visa they don't have: checks the passport against sourced airport transit visa lists (UK, Germany, France, Netherlands; US has no airside transit) and the traps that force you through the border (self-transfer, onward Schengen flight, UK to Ireland, leaving the airport), applies the documents that exempt you, and links the official source and Timatic.", category: "Context and awareness", Demo: TransitVisaCheckDemo },
  { name: "llm-cost-estimate", title: "LLM Cost Estimate", description: "Stops a batch or long prompt running up a surprise API bill: before it runs it estimates input and output tokens and the cost from your own dated price table, shows the worst case when max_tokens is missing, catches a request over the context window, a run many times the last one and a premium model picked for a bulk job, and fixes each in one tap (set max_tokens, switch model), with a Run button that states the cost, and shows the Batch API saving on bulk jobs.", category: "Context and awareness", Demo: LlmCostEstimateDemo },
  { name: "kube-context-guard", title: "Kube Context Guard", description: "Stops kubectl and helm commands landing on the wrong cluster or namespace by showing, before they run, the context, cluster (EKS ARNs and GKE names shortened) and namespace they will really use, a --context or --kube-context flag included, and flagging production (read word by word, so pre-prod and nonprod aren't), a deploy into the default namespace, a manifest namespace that disagrees with -n (which kubectl refuses but helm silently splits from the release) and a context switched since the last command, each with a one-tap fix such as a server dry run, and asking for the context name before a production change.", category: "Context and awareness", Demo: KubeContextGuardDemo },
  { name: "security-event-log", title: "Security Event Log", description: "Stops an account takeover hiding among routine entries: risky changes from other devices are highlighted, and a burst of them (a new device, then 2-step verification off, then a new recovery email) is grouped and named as a likely takeover, every row has a \"This wasn't me\" path that lists each step it will take (sign the device out, turn 2-step back on, restore recovery details...) as a checkbox the user can untick before it acts, and days and times follow the account's time zone with relative time.", category: "Context and awareness", Demo: SecurityEventLogDemo },
  { name: "dst-shift-notice", title: "DST Shift Notice", description: "Stops a recurring meeting silently moving by an hour for part of the team when daylight saving changes on different dates (the US and EU weeks apart, India never), listing each attendee's affected dates with the new local time, the clock change behind it and moves outside working hours, and offering to fix the series to the organiser's zone or UTC with a count of who moves under each.", category: "Context and awareness", Demo: DstShiftNoticeDemo },
  { name: "environment-badge", title: "Environment Badge", description: "Stops edits in the wrong environment by marking the page, tab title (kept through navigation) and favicon with PRODUCTION, STAGING or DEV (production hatched in red), reading names like \"eu-prod-2\" word by word and never calling an unknown environment safe, plus a hook that asks for confirmation only in production.", category: "Context and awareness", Demo: EnvironmentBadgeDemo },
  { name: "acting-as-banner", title: "Acting As Banner", description: "Prevents changing a customer's data while thinking it's your own with a sticky 'You're acting as…' bar and an org chip that makes every destructive button say where it acts.", category: "Context and awareness", Demo: ActingAsBannerDemo },
  { name: "offline-banner", title: "Offline Banner", description: "Stops people assuming their actions reached the server by counting queued changes while offline, staying up after reconnecting until the queue has actually synced, and offering Retry if the sync fails.", category: "Context and awareness", Demo: OfflineBannerDemo },
  { name: "stale-data-notice", title: "Stale Data Notice", description: "Stops people acting on out-of-date numbers by noticing when a tab comes back after a while or the data passes its max age, and offering a one-tap refresh.", category: "Context and awareness", Demo: StaleDataNoticeDemo },
  { name: "conflict-banner", title: "Conflict Banner", description: "Stops one person silently overwriting another's edit by naming who changed the record, showing a word diff, and confirming how many of their words 'Keep mine' would replace until you've compared.", category: "Context and awareness", Demo: ConflictBannerDemo },
  { name: "session-timeout", title: "Session Timeout", description: "Stops surprise logouts that lose unsaved work by warning before an idle session expires, with rolling countdown digits and a draining ring that turns red in the last 10 seconds, cross-tab activity sync and calm screen-reader announcements.", category: "Context and awareness", Demo: SessionTimeoutDemo },
  { name: "do-not-close", title: "Do Not Close", description: "Stops people closing the tab mid-payment, upload or migration with a close warning, a marked tab title, a rolling-rate time-left estimate, a clear 'Safe to close' when done and a Retry when it fails.", category: "Context and awareness", Demo: DoNotCloseDemo },
  { name: "timezone-mismatch", title: "Timezone Mismatch", description: "Stops travellers misreading every time by hours: when the device's time zone differs from the account's, it shows both clocks ticking side by side, asks once whether to use the device zone, confirms the answer without losing focus and remembers it per pair of zones, comparing every real clock change from the tz database so zones that only drift apart for a few days (Jerusalem and Athens) still count as different.", category: "Context and awareness", Demo: TimezoneMismatchDemo },
  { name: "update-available", title: "Update Available", description: "Gets people onto a new deploy without losing work: it polls a version endpoint (or takes a prop), explains what a refresh does, never refreshes while there are unsaved changes and offers \"Refresh after I save\" instead, and lets \"Later\" skip only that build.", category: "Context and awareness", Demo: UpdateAvailableDemo },
  { name: "revision-banner", title: "Revision Banner", description: "Stops people mistaking an old revision for the current document or editing it by accident: the content is locked in a striped frame that explains blocked edits, and \"Restore this version\" confirms which latest version it replaces and how many words change.", category: "Context and awareness", Demo: RevisionBannerDemo },
  { name: "filter-notice", title: "Filter Notice", description: "Stops people thinking data is missing or bulk-acting on a partial set: it says how many items active filters hide, shows each filter as a removable chip with how many items it hides on its own, and warns when selected items are hidden.", category: "Context and awareness", Demo: FilterNoticeDemo },
  { name: "disabled-reason", title: "Disabled Reason", description: "Stops dead-end disabled buttons by keeping the control focusable with aria-disabled and explaining on hover, focus or tap exactly what blocks it, in a portalled panel no overflow-hidden toolbar can clip, with a one-tap jump to each fix, a shake when a blocked press lands and each cleared blocker sliding out of the list.", category: "Context and awareness", Demo: DisabledReasonDemo },
  { name: "quota-forecast", title: "Quota Forecast", description: "Stops teams hitting a usage limit by surprise by projecting the current rate to the reset (\"At this pace you'll run out Thu 22 Oct\"), turning amber or red on that forecast, and saying what happens at the limit.", category: "Context and awareness", Demo: QuotaForecastDemo },
  { name: "resume-marker", title: "Resume Marker", description: "Stops readers losing their place in long feeds and docs by remembering the item they rested on, marking it \"You were here\" on return, and offering a jump there (and back) instead of moving the page on its own.", category: "Context and awareness", Demo: ResumeMarkerDemo },
  { name: "new-content-pill", title: "New Content Pill", description: "Stops live feeds shifting posts under the reader's finger by holding new arrivals behind a \"5 new posts\" pill that inserts and scrolls up on tap, inserting directly only when the reader is at the top (or scrolls back up to it) and not mid-press; works in its own scroll box or on a page that scrolls as a whole (scrollTarget=\"window\").", category: "Context and awareness", Demo: NewContentPillDemo },
  { name: "presence-lock", title: "Presence Lock", description: "Stops two people silently overwriting each other's edit of the same field: it shows who is editing what (\"Priya is editing Price\"), softly locks that field in their colour with an \"Edit anyway\" that warns once, never locks someone already typing, and releases locks held by people who went idle; transport-agnostic, with animated join and leave.", category: "Context and awareness", Demo: PresenceLockDemo },
  { name: "unsent-marker", title: "Unsent Marker", description: "Stops people believing they replied when their text never left the box: a left-behind draft comes back as a dashed \"Not sent · Priya hasn't received it\" bubble in the thread, right where the reply would be, with Send, Edit and a two-tap Discard, plus a \"Not sent:\" preview for conversation lists.", category: "Context and awareness", Demo: UnsentMarkerDemo },
  { name: "presenter-mode", title: "Presenter Mode", description: "Stops emails, amounts and keys leaking on a screen share: values wrapped in <Sensitive> are removed from the page (not blurred) behind fixed-length masks while presenting, a visible Presenting bar shows the mode is on, a deliberate hold peeks one value, and starting getDisplayMedia in the tab suggests turning it on.", category: "Context and awareness", Demo: PresenterModeDemo },
  { name: "locale-notice", title: "Locale Notice", description: "Stops numbers and dates being misread across locales by showing the value as you write it and as the reader's locale writes it, saying exactly what they would take it to mean (\"In Germany, 1,000 reads as 1\"), offering a form neither side can flip, and catching numbers typed with the other convention's decimal mark (\"1,5\" becoming 15).", category: "Context and awareness", Demo: LocaleNoticeDemo },
  { name: "progress-heartbeat", title: "Progress Heartbeat", description: "Stops people waiting on a dead job or killing a live one by telling working from stalled (no heartbeat for N seconds → \"No progress for 40s\" with Retry), separating \"alive but not advancing\" from silence, showing a time-left range that widens instead of a jumpy countdown, and holding the bar at 99% until the job reports done.", category: "Context and awareness", Demo: ProgressHeartbeatDemo },
  { name: "account-switch-guard", title: "Account Switch Guard", description: "Prevents acting as the wrong account when several are signed in by naming who the action runs as and who it is not ('Posting as Acme Corp, not Tushar'), and by catching a switch made in another tab so the button changes to name the page's account instead of silently acting as the new one.", category: "Context and awareness", Demo: AccountSwitchGuardDemo },
  { name: "maintenance-window", title: "Maintenance Window", description: "Prevents work lost to planned downtime with a banner in the reader's own time zone whose countdown sharpens as it nears, a start button that warns when a long job would be cut off, and a read-only state during the window that keeps unsaved edits in place and guards against reloads.", category: "Context and awareness", Demo: MaintenanceWindowDemo },
  { name: "permission-pre-ask", title: "Permission Pre-Ask", description: "Prevents a wasted one-shot browser permission prompt by explaining why and what for in the page before calling the real API, telling a closed prompt from a block, and showing this browser's exact re-enable steps, then flipping to on by itself once the user allows it.", category: "Context and awareness", Demo: PermissionPreAskDemo },
  { name: "clock-skew", title: "Clock Skew", description: "Catches a device clock that's off from server time (Date header or prop), says by how much and what breaks because of it (authenticator codes, \"expires in\" timers, secure sites), and corrects the countdowns inside it; the warning clears itself once the clock is fixed.", category: "Context and awareness", Demo: ClockSkewDemo },
  { name: "private-mode-notice", title: "Private Mode Notice", description: "Warns before someone relies on drafts or “Remember me” in a browser that won't keep them (private window, blocked site data or a full quota), proving it with a real write test before guessing, offering to export unsaved work and guarding the tab from closing.", category: "Context and awareness", Demo: PrivateModeNoticeDemo },
  { name: "experimental-badge", title: "Experimental Badge", description: "Stops people trusting an unfinished feature blindly: the badge opens a plain list of concrete risks (work may be lost, things may change or disappear), a feedback link and a one-tap switch back to the stable version that says what happens to their work.", category: "Context and awareness", Demo: ExperimentalBadgeDemo },
  { name: "retry-after", title: "Retry After", description: "Stops rate-limit spam from extending a lockout: on 429/503 it reads Retry-After (seconds or a server-dated time) and RateLimit headers, explains which limit was hit and when it resets, counts down, swallows impatient clicks and retries automatically with jitter while the user's input stays put.", category: "Context and awareness", Demo: RetryAfterDemo },
  { name: "low-battery-guard", title: "Low Battery Guard", description: "Stops a long upload, export, call or exam dying halfway on a flat battery: before it starts it compares the battery's runway (to a safety reserve, from the Battery Status API or a measured drain rate) with the task's length, draws where the battery would cut it off, and offers \"Start when plugged in\", which starts the task the moment a charger connects, staying silent when the task will finish anyway.", category: "Context and awareness", Demo: LowBatteryGuardDemo },
  { name: "data-cost-notice", title: "Data Cost Notice", description: "Stops a big download, upload or autoplay eating a data plan or hanging on a slow line: on Data Saver, mobile data or a slow connection (Network Information API, or a Save-Data header passed in) it shows the size and an honest rough time (never calling a line at Chrome's 10 Mbps cap slow, uploads as \"over\"), offers the lighter version with what it saves, or waits for Wi-Fi and then starts by itself.", category: "Context and awareness", Demo: DataCostNoticeDemo },
  { name: "sunset-notice", title: "Sunset Notice", description: "Stops an API shutdown arriving as a surprise outage: it reads the Sunset (RFC 8594) and Deprecation (RFC 9745) headers and their Link relations off a response, lists exactly what stops working, shows when in the reader's own zone (flagging when that falls on a different day than the header's UTC date), counts down while turning amber then red, and lets \"Remind me later\" snooze only until the next 30/7/1-day mark.", category: "Context and awareness", Demo: SunsetNoticeDemo },
  { name: "print-guard", title: "Print Guard", description: "Stops the printout that doesn't match the screen: before printing it finds light text on dark backgrounds the browser will drop, collapsed sections, tables wider than the page (measured at their narrowest), scroll boxes that print only what's in view and links without their address, offers print-only fixes that never change the screen, and since Ctrl+P can't be stopped, fixes those printouts automatically and offers a review.", category: "Context and awareness", Demo: PrintGuardDemo },
  { name: "bcc-guard", title: "Bcc Guard", description: "Stops a group email exposing everyone on it by showing the To line exactly as one recipient will see it, counting the names, private addresses and companies it gives away, flagging when being on the list is itself sensitive (\"HIV\", \"arrears\") and offering one email each, moving every outside recipient to Bcc in one tap with Undo, and asking for a second press to send while addresses still show.", category: "Sharing, sending and paying", Demo: BccGuardDemo },
  { name: "hidden-content-check", title: "Hidden Content Check", description: "Stops a shared spreadsheet, document or deck leaking what isn't on screen by opening the .xlsx, .docx or .pptx in the browser before it goes out, with no dependencies, and listing hidden and very hidden sheets, hidden rows and columns, tracked deletions, hidden text, comments, speaker notes, hidden slides, embedded workbooks, links to internal drives and author details, opening on the worst one with the hidden tab's real first rows, letting each be kept or removed (the cleaned file is re-checked) and asking for a second press to share with items still open.", category: "Sharing, sending and paying", Demo: HiddenContentCheckDemo },
  { name: "prompt-data-guard", title: "Prompt Data Guard", description: "Stops customer data, secrets and confidential documents going into an AI chat by saying before send exactly what goes where and for how long (\"248 customer rows and a CONFIDENTIAL doc will go to OpenAI, kept up to 30 days\"), counting table rows and every cell in a name column (and every other mention of those names) alongside checked emails, phones, cards, Aadhaar, PAN and API keys across the message and its attachments, then sending in one tap with consistent stand-ins (‹EMAIL_1›) whose mapping stays on the device so restoreStandIns() puts the real values back into the reply, with a second press needed to send the real data.", category: "Sharing, sending and paying", Demo: PromptDataGuardDemo },
  { name: "bill-split-check", title: "Bill Split Check", description: "Stops a bill split that quietly overcharges someone by checking an item-by-item split against the printed receipt, catching unclaimed items, tax counted twice, a tip on top of a service charge, a total that doesn't match and what an equal split costs the lightest eater, each with a one-tap fix and Undo, with shares rounded by largest remainder so they always add up and each row saying who owes the payer what.", category: "Sharing, sending and paying", Demo: BillSplitCheckDemo },
  { name: "callback-number-check", title: "Callback Number Check", description: "Stops expensive and scam callbacks by saying what a number you're about to call back really is (country and line type, from libphonenumber) and flagging a Caribbean +1 876 number posing as a US area code, a one-ring missed call from abroad, premium-rate and shared-cost lines, toll-free numbers that are only free in their own country, unassigned ranges and a 'bank' number missing from the bank's published list, with risky calls needing a second press as the Call button morphs into 'Call anyway' in place.", category: "Sharing, sending and paying", Demo: CallbackNumberCheckDemo },
  { name: "quote-lock", title: "Quote Lock", description: "Stops paying a re-quoted price you never saw: it shows a held FX, swap or fare quote draining, fetches a fresh one when the hold ends (skew-proof with validFor), rolls the amount from old to new with the difference called out, turns a worse-than-tolerance price into an explicit Accept step by morphing the Pay button in place, re-quotes a Pay pressed in the hold's last seconds, keeps the amount in the Pay label, and ignores stale responses and double presses.", category: "Sharing, sending and paying", Demo: QuoteLockDemo },
  { name: "calendar-external-guest-guard", title: "Calendar External Guest Guard", description: "Stops an internal meeting invite reaching outside guests with more than you meant to share: it names who is outside your domains (and a colleague's personal Gmail standing in for their work address, with the work address one tap away), then lists what those guests really get under Google Calendar's rules, such as an agenda line marked internal, a file name they can read even without access, an \"anyone with the link\" attachment, the guest list and invite or edit rights, each with a one-tap fix and Undo, and asks for a second, deliberate press before sending with serious items still open.", category: "Sharing, sending and paying", Demo: CalendarExternalGuestGuardDemo },
  { name: "chat-audience-check", title: "Chat Audience Check", description: "Stops a sensitive message landing in a group chat with someone who shouldn't be there (the slip that put a journalist, shown only as \"JG\", in US officials' Signal chat in 2025): before it sends it flags members whose name disagrees with what you saved them as, names nobody can identify, people who joined after your last message and people from outside your organisation, stays a quiet one-liner for ordinary messages, and when the text looks sensitive or an identity doesn't add up lists those people with Remove, View profile and \"I know them\" and needs a second, deliberate press to send.", category: "Sharing, sending and paying", Demo: ChatAudienceCheckDemo },
  { name: "out-of-office-check", title: "Out of Office Check", description: "Stops an auto-reply that says the wrong thing to the wrong people: it reads back exactly when replies go out (Gmail's end date runs to 11:59 PM) and who gets which text, compares the dates with the return date written in the message to catch replying all day on the day you're back, stopping days early, no end date and a date left over from last time, and flags outside replies that give strangers a phone number, a colleague's direct address, where you are or a health reason, or that answer every outside sender, each with a one-tap fix and Undo.", category: "Sharing, sending and paying", Demo: OutOfOfficeCheckDemo },
  { name: "retract-window", title: "Retract Window", description: "Stops people trusting an unsend or edit that won't work: under a sent message it shows how long Edit and Unsend really stay open on that platform (sourced iMessage, WhatsApp and Slack presets, or your own) with a draining bar that turns amber near the end, says who has already read it and whose app will keep the original anyway, keeps \"Delete for me\" apart and labelled as leaving everyone else's copy, reports who still has it after an unsend, and offers a correction once the windows close, announcing only a window closing, never the countdown.", category: "Sharing, sending and paying", Demo: RetractWindowDemo },
  { name: "card-bill-pay", title: "Card Bill Pay", description: "Stops a credit card bill being paid in a way that quietly costs interest by reading back, before Pay, what the chosen amount really does: anything short of the total (even 40 paise, unless the statement forgives that shortfall) loses the interest-free days on the whole bill and on new purchases, the minimum is turned into years and rupees of interest, and below the minimum or past RBI's 3-day grace it shows the late fee and the credit-bureau report, with one tap to pay the total.", category: "Sharing, sending and paying", Demo: CardBillPayDemo },
  { name: "otp-share-guard", title: "OTP Share Guard", description: "Stops people reading a one-time code out to a scammer by saying in one sentence what it really approves (\"This code approves a ₹24,999 payment to Croma\", \"This code logs in a new device\"), and, when the app knows a call or screen share is active or the code is for a different action than the user started, switching to a strong never-share warning with press-and-hold to see the code, a delayed Copy, a code that is never drawn while the screen is shared, and a one-tap \"I didn't request this\".", category: "Sharing, sending and paying", Demo: OtpShareGuardDemo },
  { name: "bank-transfer-timing", title: "Bank Transfer Timing", description: "Prevents Indian bank transfers that get refused or land later than expected by reading back when the money arrives on the chosen rail (seconds on IMPS and UPI, the next half-hourly NEFT batch and its 2-hour credit window, RTGS within 30 minutes, branch hours and holidays), catching RTGS under ₹2 lakh, IMPS over ₹5 lakh, UPI over its category cap, the bank's own daily limit and a new payee's cooling period and first-day cap with the rail that works one tap away, and spelling the amount out in lakh and crore.", category: "Sharing, sending and paying", Demo: BankTransferTimingDemo },
  { name: "gift-card-scam-guard", title: "Gift Card Scam Guard", description: "Stops someone paying a scammer with gift cards: at checkout it spots the classic patterns (a large total, several cards, a note about a boss, tax, police, a refund or tech support, sending the codes, a first gift card order), says plainly that no real company or agency takes payment in gift cards, and won't continue until the user answers one question, with \"someone asked me to\" ending at a stop screen instead of payment. Size limits follow the order's currency, and scam phrases include common Hinglish and Hindi ones such as \"sir ne bola\".", category: "Sharing, sending and paying", Demo: GiftCardScamGuardDemo },
  { name: "commit-secret-guard", title: "Commit Secret Guard", description: "Stops a credential going into a commit by scanning only the lines a diff adds for provider keys, private keys, passwords in URLs, hard-coded secrets and high-entropy strings, flagging .env and key files, ignoring test fixtures by pattern (except live key formats), and offering per-finding fixes (move to an env variable, remove the line, or mark a false positive) with a rotate-now warning when the change is already pushed.", category: "Sharing, sending and paying", Demo: CommitSecretGuardDemo },
  { name: "publish-preview", title: "Publish Preview", description: "Stops an npm publish shipping the wrong files or failing for good by previewing the npm pack --dry-run --json tarball and flagging .env files and keys, source maps, tests, repo config, large files, entry points missing from the build (with the reason: .gitignore fallback, files list or no build), a version that's already published, private: true and a missing files allowlist, with one-tap fixes that wait for a fresh pack before they count.", category: "Sharing, sending and paying", Demo: PublishPreviewDemo },
  { name: "upi-autopay-review", title: "UPI AutoPay Review", description: "Stops a ₹199 plan being approved as a ₹9,999 \"as presented\" mandate that never ends by reading the cap, schedule, validity and merchant back against the plan before the PIN, flagging a cap far above the price, no fixed schedule, no end date, the wrong merchant and debits above the RBI PIN-free limit, with one-tap fixes to cap it at the plan price or end it in a year.", category: "Sharing, sending and paying", Demo: UpiAutopayReviewDemo },
  { name: "upi-collect-guard", title: "UPI Collect Guard", description: "Stops people \"entering their PIN to receive\" money by showing a collect request as the payment it is (You pay ₹4,999 to…), asking whether they expect money and turning a yes into a decline-only stop, and flagging refund, prize, OLX-buyer and KYC wording, person-to-person collects (switched off by NPCI on 1 Oct 2025), unknown requesters and small test amounts before the PIN screen.", category: "Sharing, sending and paying", Demo: UpiCollectGuardDemo },
  { name: "tds-invoice-total", title: "TDS Invoice Total", description: "Stops Indian freelancers being short-paid by working out fee + GST − TDS = what lands in the bank, with the right rate and section for the invoice date (10% professional, 2% technical, 1%/2% contract; s.393 of the 2025 Act, was 194J/194C) and the yearly threshold, then flagging TDS taken on the GST, the wrong rate and the 20% rate without a PAN, with a one-tap fix and a ready note for the client.", category: "Sharing, sending and paying", Demo: TdsInvoiceTotalDemo },
  { name: "link-access-check", title: "Link Access Check", description: "Prevents \"I can't open the link\" and accidental public sharing by checking every Google Drive, OneDrive, Dropbox, Notion, Figma or Box link in a message against its recipients before it is sent, naming who can't open each one with one-tap fixes (give view access, open it to the company, or ask the owner when you can't share it), and warning when an anyone-with-the-link doc is going outside the organisation.", category: "Sharing, sending and paying", Demo: LinkAccessCheckDemo },
  { name: "reply-all-guard", title: "Reply All Guard", description: "Stops the reply all nobody wanted by stating how many people it really reaches (distribution lists expanded), naming everyone outside the organisation by domain, catching a BCC'd or forwarded-to recipient about to reveal themselves (without false alarms when the mail came through a list you're on) and a Reply-To that points elsewhere, with one tap to reply to the sender only or leave out external people, and Undo.", category: "Sharing, sending and paying", Demo: ReplyAllGuardDemo },
  { name: "duplicate-payment-guard", title: "Duplicate Payment Guard", description: "Stops paying the same payee the same amount twice by telling a double tap (swallowed, charged once), a retry after a timeout (the first may still land, so it offers Check status before paying again) and a deliberate repeat (\"You paid Ravi ₹2,400 12 min ago\", needing a separate second press) apart.", category: "Sharing, sending and paying", Demo: DuplicatePaymentGuardDemo },
  { name: "bulk-send-guard", title: "Bulk Send Guard", description: "Stops an SMS, WhatsApp or email blast going out wrong by stating before send how many it reaches, how many opted out and are left out, who is in quiet hours in their own time zone (held until morning by default), the cost and a jump over the last send, then requiring an explicit confirm that a double click can't trigger, with the count typed when the jump is big.", category: "Sharing, sending and paying", Demo: BulkSendGuardDemo },
  { name: "pii-post-guard", title: "PII Post Guard", description: "Stops people posting their phone number, email, address, Aadhaar, PAN, card number or an OTP to a public feed, comment or review by saying who will see it, finding each detail with real checks (Verhoeff, Luhn, PAN holder type, OTP keywords) rather than loose digit runs, and masking one or all of them in one tap the way each format expects (XXXX XXXX 1234).", category: "Sharing, sending and paying", Demo: PiiPostGuardDemo },
  { name: "recurring-charge-readback", title: "Recurring Charge Readback", description: "Prevents trial-to-paid and intro-price surprises by reading back, next to the subscribe button, what's charged today, when the first real charge and any price step-up land, and the exact cancel-by time with zone, and by flagging a trial too short to cancel in time or a button whose words (\"free\", \"₹499/mo\" on yearly billing) disagree with the charge.", category: "Sharing, sending and paying", Demo: RecurringChargeReadbackDemo },
  { name: "gst-invoice-check", title: "GST Invoice Check", description: "Stops GST invoices going out under the wrong tax head by comparing the supplier GSTIN's state code with the place of supply to pick CGST + SGST/UTGST or IGST (SEZ and exports always IGST), then checking each rate against the slabs in force on the invoice date (including the 28% slab ending on 1 Feb 2026), zero-rated LUT exports, the CGST/SGST split, every amount and the total, with a one-tap fix.", category: "Sharing, sending and paying", Demo: GstInvoiceCheckDemo },
  { name: "role-preview", title: "Role Preview", description: "Prevents over-granting access by showing exactly what the chosen role can and can't do, diffing it against the current role, and suggesting a smaller role when the pick adds dangerous permissions.", category: "Sharing, sending and paying", Demo: RolePreviewDemo },
  { name: "visibility-picker", title: "Visibility Picker", description: "Prevents accidental oversharing: narrowing is instant, but widening (a riskier level or simply more people) shows exactly who gains access and only goes through on an explicit confirm, so a double-click or arrow key can't publish anything; levels a policy blocks say why, and a failed save puts the old level back and says so.", category: "Sharing, sending and paying", Demo: VisibilityPickerDemo },
  { name: "recipient-check", title: "Recipient Check", description: "Prevents misaddressed email by marking external recipients in amber, catching typo'd and lookalike domains with a one-tap fix, blocking duplicates, spotting a name paired with someone else's address, and warning when a message goes to too many people.", category: "Sharing, sending and paying", Demo: RecipientCheckDemo },
  { name: "secret-paste-guard", title: "Secret Paste Guard", description: "Stops credentials leaking into chats and forms by spotting API keys, tokens, JWTs, private keys and high-entropy strings as they are pasted or typed, then offering one-tap Redact (keeping the last 4) or Keep.", category: "Sharing, sending and paying", Demo: SecretPasteGuardDemo },
  { name: "external-link", title: "External Link", description: "Prevents clicking through to a phishing or unexpected site by confirming off-site links with the real ASCII destination and its registrable domain in bold, and flagging punycode, lookalike domains, link text that disagrees with the href, buried brand names, raw IPs and plain http.", category: "Sharing, sending and paying", Demo: ExternalLinkDemo },
  { name: "charge-summary", title: "Charge Summary", description: "Prevents surprise charges by showing today's amount, the first charge and renewal dates, taxes and one-time credits upfront, and a plain-language sentence of what you'll pay.", category: "Sharing, sending and paying", Demo: ChargeSummaryDemo },
  { name: "send-time-check", title: "Send Time Check", description: "Prevents messages landing at 2 AM, on the recipient's weekend (including Friday–Saturday weekends) or on a holiday by showing their local time next to Send on a strip of their day (night, working hours, now), and offering a one-tap schedule for the start of their next working day that glides the marker to the slot it picks.", category: "Sharing, sending and paying", Demo: SendTimeCheckDemo },
  { name: "fill-before-copy", title: "Fill Before Copy", description: "Prevents pasting broken commands that still contain <YOUR_API_KEY> or {{project_id}} by turning each placeholder into an inline field and blocking Copy (or asking once) until all of them are filled.", category: "Sharing, sending and paying", Demo: FillBeforeCopyDemo },
  { name: "photo-location-guard", title: "Photo Location Guard", description: "Stops a photo from publicly revealing where and when it was taken by reading its EXIF and XMP before upload (GPS with its precision, capture time, camera serial, a hidden uncropped preview) and offering a one-tap \"Remove location\" that re-encodes the photo upright and re-checks the result.", category: "Sharing, sending and paying", Demo: PhotoLocationGuardDemo },
  { name: "currency-hint", title: "Currency Hint", description: "Prevents budgeting on the wrong number when paying abroad by showing a foreign price with a clearly approximate, dated conversion (\"€49.00 ≈ ₹4,520\"), pricing a merchant's dynamic currency conversion against the reference rate with a one-tap switch back to the local currency, estimating card fees and flagging stale rates.", category: "Sharing, sending and paying", Demo: CurrencyHintDemo },
  { name: "mention-guard", title: "Mention Guard", description: "Prevents accidental mass pings by saying, as you type, how many people @channel, @everyone or a group mention will notify and how many are in other time zones, flagging mentioned people who aren't in the conversation, offering one-tap fixes, and turning Send into an explicit \"Notify 1,240 people\" confirm that a double press can't trigger.", category: "Sharing, sending and paying", Demo: MentionGuardDemo },
  { name: "share-link", title: "Share Link", description: "Prevents oversharing through links by reading every setting back as one sentence (\"Anyone with the link can edit until Fri 16 Oct, 5:00 PM\"), warning on public edit access and open-ended public links with one-tap fixes, showing a live expiry countdown, flagging when you widen a link you've already copied, and confirming before revoking.", category: "Sharing, sending and paying", Demo: ShareLinkDemo },
  { name: "merge-field-check", title: "Merge Field Check", description: "Prevents bulk emails and SMS going out as \"Hi ,\" or \"{{frist_name}}\" by rendering the template for each real recipient, flagging unknown fields, broken braces and recipients with no value (spaces count as empty) with one-tap fixes and fallbacks, and stepping straight to the recipients who would get a gap.", category: "Sharing, sending and paying", Demo: MergeFieldCheckDemo },
  { name: "forward-guard", title: "Forward Guard", description: "Prevents oversharing when forwarding or sharing a thread by listing what the new recipients will see for the first time (earlier messages, internal notes, attachments, other people's addresses), skipping messages they were already on, trimming internal notes by default and letting each item be dropped before it goes.", category: "Sharing, sending and paying", Demo: ForwardGuardDemo },
  { name: "payee-check", title: "Payee Check", description: "Prevents paying the wrong account by asking the bank who holds it (a pluggable async lookup) and comparing that with the typed name like Confirmation of Payee: match, close match with the real name one tap away, or no match with the name kept hidden and an explicit pay-anyway, plus callouts for first-time payees and large first payments.", category: "Sharing, sending and paying", Demo: PayeeCheckDemo },
  { name: "csv-export-guard", title: "CSV Export Guard", description: "Stops spreadsheets silently corrupting an export by previewing what each column opens as (phone numbers and PIN codes losing leading zeros or their +, long IDs becoming 1.23457E+15, \"3-4\" turning into a date, cells starting with = + - @ running as formulas) and offering a per-column fix that forces text or neutralises the formula.", category: "Sharing, sending and paying", Demo: CsvExportGuardDemo },
  { name: "link-unfurl-check", title: "Link Unfurl Check", description: "Shows how a link will unfurl before you post it (title, description and image from a pluggable Open Graph fetch) and catches localhost and staging URLs with a swap to the live site, tracking parameters with a one-tap strip, redirects (flagged hard when they land on a sign-in page), and missing or undersized preview images.", category: "Sharing, sending and paying", Demo: LinkUnfurlCheckDemo },
  { name: "qr-share", title: "QR Share", description: "Stops a QR code going out that opens the wrong thing by reading the exact URL back under the code, re-decoding the code it drew to prove nothing was truncated, and warning about localhost, staging, http, invisible characters and links long enough to make a dense code, with one-tap fixes; ships its own dependency-free encoder (byte mode, ECC M).", category: "Sharing, sending and paying", Demo: QrShareDemo },
  { name: "redact-image", title: "Redact Image", description: "Stops a “redacted” screenshot from leaking what it hides: solid boxes only (blur and pixelation can be reversed), padded and snapped to whole pixels, placeable by drag or keyboard, suggestions from a pluggable text detector with an amber nudge for anything sensitive left uncovered, and an export flattened to a fresh PNG that is re-read to prove every box is solid, with no metadata and no aCropalypse-style data after the image end.", category: "Sharing, sending and paying", Demo: RedactImageDemo },
  { name: "sms-segments", title: "SMS Segments", description: "Prevents bulk SMS costing double by splitting the text into the parts carriers bill, naming the curly quote or emoji that forced UCS-2 ('this ’ makes it 3 messages instead of 2'), fixing it in one tap, and reading the total back per recipient count.", category: "Sharing, sending and paying", Demo: SmsSegmentsDemo },
  { name: "export-scope", title: "Export Scope", description: "Stops an export quietly going out as page 1 of 250, silently capped, or full of personal data by reading back exactly what the file holds (rows and page, filters, the date range as real dates with a day count, hidden and personal-data columns) with toggles and a one-tap \"Export all\" or \"Mask it\" fix.", category: "Sharing, sending and paying", Demo: ExportScopeDemo },
  { name: "invite-check", title: "Invite Check", description: "Stops a calendar invite landing at 3 AM, on a guest's weekend or holiday, at a typo'd company domain, with no video link or location, or twice, by showing the start in every guest's own zone, offering the nearest start that suits everyone in one tap, and catching duplicate guests hidden by +tags or Gmail dots and invites already sent.", category: "Sharing, sending and paying", Demo: InviteCheckDemo },
  { name: "large-attachment", title: "Large Attachment", description: "Prevents the message that bounces for being too big by checking attachments against each service's real limit (counting email's ~37% Base64 encoding overhead), marking the fewest files that push it over, and showing the resulting size of sending them as a link or compressing, with an honest estimate for files that are already compressed.", category: "Sharing, sending and paying", Demo: LargeAttachmentDemo },
  { name: "embed-code", title: "Embed Code", description: "Prevents pasting an embed that leaks or breaks by reading back what visitors will see and what it tracks, offering a privacy mode and allowed-site list, and catching drafts, private resources and secrets in the URL (token=, sig=) with a one-tap strip before a deliberate second click copies it.", category: "Sharing, sending and paying", Demo: EmbedCodeDemo },
  { name: "alt-text-check", title: "Alt Text Check", description: "Prevents posting images screen readers can't use by checking each one's alt text for missing text, filenames (IMG_2041.jpg, PXL_…), \"image of…\" redundancy, copies of the caption and excess length, with per-image status chips, one-tap fixes, a decorative toggle, a words-in-the-image reminder for screenshots, and a post button that jumps to the first problem before posting anyway.", category: "Sharing, sending and paying", Demo: AltTextCheckDemo },
  { name: "stale-reply", title: "Stale Reply", description: "Prevents replying to a conversation that has moved on by warning \"This was 3 weeks ago and 14 newer messages followed\", surfacing the newest related messages (and any that already settled it, like \"fixed in 2.4.1\"), and offering to reply to the latest or quote the original for context.", category: "Sharing, sending and paying", Demo: StaleReplyDemo },
  { name: "tip-picker", title: "Tip Picker", description: "Prevents overtipping by saying whether the percent is on the pre-tax or post-tax amount (with a switch), showing every preset in money that rolls to its new value when the base changes, flagging a service charge already on the bill, and holding back accidental huge tips (250 typed in the % field, 15 typed as money, 100% that doubles the bill), struck through in the summary, until they're fixed in one tap or confirmed.", category: "Sharing, sending and paying", Demo: TipPickerDemo },
  { name: "refund-picker", title: "Refund Picker", description: "Prevents refund surprises and disputes by letting staff or customers pick units per item (or a set amount that can't exceed what the items allow), naming every restocking and return-shipping deduction, keeping non-refundable items visible with the reason, showing each refund method's own net amount and real arrival dates, and reading the whole refund back in one sentence before it's issued.", category: "Sharing, sending and paying", Demo: RefundPickerDemo },
  { name: "plan-change-readback", title: "Plan Change Readback", description: "Prevents surprise charges and lost data on upgrades and downgrades by prorating by day (credit for unused time, charge today, next bill amount and date), saying plainly that a downgrade credit goes to future bills rather than the card, comparing switching now with switching at period end, listing features lost, and showing usage already over the new plan's limits with what happens to the excess, which must be acknowledged before a destructive change.", category: "Sharing, sending and paying", Demo: PlanChangeReadbackDemo },
  { name: "payment-reference", title: "Payment Reference", description: "Prevents bank transfers that can't be matched to an invoice by requiring the invoice number in the expected format (with one-tap fixes for a missing, mistyped or different invoice), checking the reference against each rail's length limit and character set (UPI and IMPS drop symbols, many NEFT remark boxes stop at 30, Faster Payments keeps 18), moving a cut-off invoice number to the front, and previewing the payee's statement line with the cut part struck through.", category: "Sharing, sending and paying", Demo: PaymentReferenceDemo },
  { name: "truncation-preview", title: "Truncation Preview", description: "Stops the point of a post vanishing behind \"…more\" by showing exactly where LinkedIn, Instagram, X, iOS and Android push and Google (by pixel width) cut the text, warning when the key phrase, a link or an @mention X won't notify sits below the fold, and fixing it in one tap by moving that sentence up or removing the blank lines that each cost a whole preview line.", category: "Sharing, sending and paying", Demo: TruncationPreviewDemo },
  { name: "dockerfile-check", title: "Dockerfile Check", description: "Stops a Dockerfile shipping a root, leaky or slow image by reading it the way BuildKit does (escape directive, continuations, heredocs, stages) and flagging a final image that runs as root, secrets in ARG or ENV (Docker's own key rule), secret files baked in or carried over by COPY --from, COPY . before the dependency install, a missing .dockerignore, apt-get without -y, --no-install-recommends or list cleanup, ADD from a URL without --checksum, curl | sh and shell-form CMD or ENTRYPOINT that swallow SIGTERM, with one-tap fixes such as secret mounts, manifest-first installs and exec form.", category: "Reading without mistakes", Demo: DockerfileCheckDemo },
  { name: "gitignore-check", title: "Gitignore Check", description: "Stops secrets and junk getting committed when a .gitignore only looks right: it runs Git's real matching rules against your files and names the line that decides each one, catching inline # comments, trailing tabs, leading spaces, backslashes and ./, ! lines that can't re-include a file inside an excluded folder or are overridden by a later line, / anchors that miss nested folders, .env, keys and node_modules left out, and already-committed files that .gitignore won't untrack (with the git rm --cached command), with one-tap fixes.", category: "Reading without mistakes", Demo: GitignoreCheckDemo },
  { name: "workflow-yaml-guard", title: "Workflow YAML Guard", description: "Stops a GitHub Actions workflow handing your repo to anyone who opens a pull request by flagging pull_request_target or workflow_run jobs that check out the PR's code (pwn requests), untrusted ${{ github.event.* }} and head_ref pasted into run scripts, actions pinned to movable tags, missing or write-all token permissions, secrets echoed, dumped with toJSON or transformed past log masking, and self-hosted runners fork PRs can reach, following GitHub Security Lab and GitHub's secure-use docs, with one-tap fixes (env indirection, read-only permissions, pull_request, a hosted runner) and Pin SHA through your own lookup.", category: "Reading without mistakes", Demo: WorkflowYamlGuardDemo },
  { name: "iam-policy-check", title: "IAM Policy Check", description: "Stops an AWS IAM or S3 bucket policy granting far more than intended by reading each statement back in plain words (who can do what, on what, only if what) and flagging full-admin and service:* wildcards, Resource \"*\", Principal \"*\" that S3 Block Public Access would call public (naming conditions such as aws:SecureTransport or a /1 IP range that don't narrow it), public reads and writes, NotAction with Allow, NotPrincipal traps and iam:PassRole on every role, with scoped one-tap fixes: your account or organization, the actions it really uses, iam:PassedToService inferred from the policy, and a Deny rewritten with aws:PrincipalArn.", category: "Reading without mistakes", Demo: IamPolicyCheckDemo },
  { name: "hreflang-check", title: "Hreflang Check", description: "Stops Google from silently ignoring hreflang by checking pasted <link> tags or a sitemap for one page or a whole set the way Search Central describes, with a who-links-to-whom grid, and flagging missing or near-miss return links, invalid codes like en-UK or es-419, relative URLs, a missing self-reference or x-default and a canonical that points at another language's page, each with a one-tap fix.", category: "Reading without mistakes", Demo: HreflangCheckDemo },
  { name: "redirect-rule-input", title: "Redirect Rule Input", description: "Stops redirect lists from breaking links, SEO and security: it reads vercel.json, Netlify _redirects or nginx rewrite/return (auto-detected) the way each platform matches, then catches loops and 2+ hop chains with the hop path, rules shadowed by an earlier wildcard, open redirects whose domain comes from the URL, 301/308 on temporary moves, 301/302 turning a POST into a GET, dropped query strings, a ?query or #hash written into the source, missing leading slashes, placeholders the source never captures, trailing-slash traps and hops to http, with a GET/POST URL tester and one-tap fixes (collapse the chain, reorder, make temporary, keep args, match the query separately).", category: "Reading without mistakes", Demo: RedirectRuleInputDemo },
  { name: "set-cookie-check", title: "Set-Cookie Check", description: "Stops cookies from being silently rejected or stolen by reading back what the browser will really do with each Set-Cookie (who gets it, over what, cross-site or not, and for how long after the 400-day cap) and flagging SameSite=None or Partitioned without Secure, broken __Host-/__Secure- prefixes, a Domain that shares a sign-in cookie with every subdomain, a missing HttpOnly, Expires and Max-Age that disagree and the 4096-byte limit, with one-tap fixes.", category: "Reading without mistakes", Demo: SetCookieCheckDemo },
  { name: "qr-scan-check", title: "QR Scan Check", description: "Prevents quishing by showing where a scanned QR code really goes before anything opens: the registrable domain in bold against what is printed beside the code (the sticker-over-the-real-code trick, with a one-tap \"Go to the printed site instead\"), lookalike and brand-borrowing domains, short links followed through a pluggable resolver, app downloads, and for UPI codes the payee, a pre-filled amount and \"scan to receive a refund\" scams.", category: "Reading without mistakes", Demo: QrScanCheckDemo },
  { name: "env-diff", title: "Env Diff", description: "Prevents broken deploys from config drift by comparing two environments key by key, putting missing and empty keys first, flagging production values that still point at localhost, a test key or the staging host, and secrets reused across both, while masking every secret behind a short fingerprint so the diff is safe to share.", category: "Reading without mistakes", Demo: EnvDiffDemo },
  { name: "join-preview", title: "Join Preview", description: "Stops a join from silently duplicating or losing rows by predicting the row count for every join type before it runs, naming the repeated keys that fan rows out, counting rows dropped for having no match or a blank key, and catching keys that never match because one side is a number and the other text, or they differ only by spaces, case or leading zeros, each with a one-tap fix that says how many rows it rescues.", category: "Reading without mistakes", Demo: JoinPreviewDemo },
  { name: "dedupe-key-picker", title: "Dedupe Key Picker", description: "Stops a dedupe from merging nothing or merging too much by previewing, as you pick the columns that define a duplicate, how many rows would merge, naming the near-unique column (like a timestamp) that keeps duplicates apart with a one-tap \"leave it out\", flagging a key so broad one value swallows a quarter of the table, keeping blank keys separate and showing sample collisions with the values a merge would discard highlighted.", category: "Reading without mistakes", Demo: DedupeKeyPickerDemo },
  { name: "dual-axis-guard", title: "Dual Axis Guard", description: "Stops a dual-axis chart from showing a correlation that isn't there by catching zero baselines at different heights and independent ranges that make a +15% line and a +140% line climb in lockstep, saying how much each series really changed, and offering a one-tap \"index both to 100\" that puts them on one honest scale (with your own chart library through a render prop, or the built-in SVG).", category: "Reading without mistakes", Demo: DualAxisGuardDemo },
  { name: "secret-field", title: "Secret Field", description: "Stops masked API keys from leaking or being pasted as dots: keeps the sk_live_/sk_test_ prefix (flagged Live or Test), re-masks on a timer or when the tab is hidden, and copying the masked text puts the real key on the clipboard.", category: "Reading without mistakes", Demo: SecretFieldDemo },
  { name: "text-diff", title: "Text Diff", description: "Prevents approving an edit you didn't see: a word-level diff that calls out changed numbers (30 → 14) and draws invisible changes like doubled spaces, line breaks and zero-width characters, in inline or split view, and stays fast on long documents with a one-word change.", category: "Reading without mistakes", Demo: TextDiffDemo },
  { name: "readback", title: "Readback", description: "Prevents misread license keys, IBANs and Wi-Fi passwords by grouping characters, labelling every look-alike (zero vs letter O, one vs small L), copying the clean value and offering a large show-to-someone view.", category: "Reading without mistakes", Demo: ReadbackDemo },
  { name: "copy-confirm", title: "Copy Confirm", description: "Prevents pasting the wrong thing by showing exactly what was copied, refusing to copy an empty value, flagging stray whitespace and invisible characters with a one-tap clean copy, and copying formatted numbers as plain text.", category: "Reading without mistakes", Demo: CopyConfirmDemo },
  { name: "middle-truncate", title: "Middle Truncate", description: "Prevents picking the wrong file, wallet or ID by truncating in the middle to the real rendered width so the distinguishing end stays visible, while copy, title and screen readers always get the full value.", category: "Reading without mistakes", Demo: MiddleTruncateDemo },
  { name: "precise-number", title: "Precise Number", description: "Prevents misread amounts by showing big numbers compactly (₹1.2 Cr, $1.2M) without ever rounding up, with the exact value in a tooltip that is never clipped by tables or scroll areas, spoken units, a lakh/crore toggle that visibly rolls the figure to its new units, and honest percentages.", category: "Reading without mistakes", Demo: PreciseNumberDemo },
  { name: "unambiguous-date", title: "Unambiguous Date", description: "Prevents DD/MM vs MM/DD misreadings by showing dates as \"3 Oct 2026\" with the distance from today, flagging numeric inputs that read two ways with a one-tap choice, and letting one answer apply to a whole imported column.", category: "Reading without mistakes", Demo: UnambiguousDateDemo },
  { name: "deadline", title: "Deadline", description: "Prevents deadlines missed to a time-zone slip or a misread midnight by showing time left plus the exact moment in your zone and the owner's, writing midnight as the end of the day before, and turning amber when close and red when overdue.", category: "Reading without mistakes", Demo: DeadlineDemo },
  { name: "change-highlight", title: "Change Highlight", description: "Stops live updates to prices, counts and statuses going unnoticed by flashing the change once (never more than once a second, skipped under reduced motion), holding a ▲/▼ with good/bad colour and the previous value on hover, and telling returning visitors what changed since their last visit.", category: "Reading without mistakes", Demo: ChangeHighlightDemo },
  { name: "spell-out", title: "Spell Out", description: "Stops booking refs, wallet addresses and passwords being misread aloud or copied wrong by grouping the characters, naming look-alikes under the glyph (0 zero vs O oh, 1/l/I, 5/S), spelling it in the NATO alphabet with case when it matters, and flagging Cyrillic look-alike letters and invisible characters.", category: "Reading without mistakes", Demo: SpellOutDemo },
  { name: "honest-bar", title: "Honest Bar", description: "Stops a bar chart from exaggerating: when the axis doesn't start at zero it draws a broken-axis mark through the axis and bars, states the distortion (\"looks 3×, really 1.09×\") with a one-tap Start at 0, tears and labels values past the scale, and reads out exact values on hover and keyboard focus, in pure SVG.", category: "Reading without mistakes", Demo: HonestBarDemo },
  { name: "change-readout", title: "Change Readout", description: "Stops changes being misread by showing them both ways (₹1,200 → ₹1,500 · +₹300 · +25%), keeping percentage points apart from percent (4% → 6% is +2 pts, +50%), refusing a % from a zero base or across zero, dividing by |base| for negatives, adding 2.5× when a value doubles, and marking whether the move is good or bad.", category: "Reading without mistakes", Demo: ChangeReadoutDemo },
  { name: "size-context", title: "Size Context", description: "Prevents failed uploads and GB-vs-GiB confusion by showing a size with a relatable comparison, transfer time and the equivalent in the other unit system (including what Windows will display), and by checking a limit before upload, flagging the grey zone where a \"4 GB\" limit only fits if the service means GiB.", category: "Reading without mistakes", Demo: SizeContextDemo },
  { name: "sum-check", title: "Sum Check", description: "Stops a wrong total from being trusted by re-adding the rows in exact arithmetic, showing the off-by amount, pointing at the rows that would explain it (swapped digits, a slipped decimal, a flipped sign, a debit on the credit side) and saying honestly when the gap is only rounding, with figures that roll to their new values so a one-tap fix is seen landing (the gap counting down to zero) and focus handed to the status after the fix.", category: "Reading without mistakes", Demo: SumCheckDemo },
  { name: "status-chip", title: "Status Chip", description: "Stops statuses being misread by never relying on colour alone (a distinct icon shape and text per tone, a colour-blind-safe palette), keeping meanings consistent through one shared status map, and explaining on hover or focus what a status means and what to do next.", category: "Reading without mistakes", Demo: StatusChipDemo },
  { name: "sort-indicator", title: "Sort Indicator", description: "Stops people misreading a table's order by stating the sort in plain words (\"Sorted by Due date, oldest first\"), warning when the order comes from a hidden column, empty values or pinned rows, and animating rows to their new place (FLIP, reduced-motion aware) so a re-sort can be followed.", category: "Reading without mistakes", Demo: SortIndicatorDemo },
  { name: "diff-table", title: "Diff Table", description: "Stops people picking the wrong plan or product from a comparison table by marking the cells that actually differ (ignoring case, spacing and 10 GB vs 10GB), offering “Show only differences” that says how many identical rows it hid, and showing blank cells as “Not stated”, never a dash that reads as “No”, while keeping those rows visible.", category: "Reading without mistakes", Demo: DiffTableDemo },
  { name: "amount-in-words", title: "Amount in Words", description: "Stops ₹2,50,000 being written or read as ₹25,00,000 by naming every digit group (2 lakh · 50 thousand), spelling the amount cheque-style in lakh/crore or million with paise or cents, showing the other number system alongside, and checking typed words against the figure, since the bank pays what the words say.", category: "Reading without mistakes", Demo: AmountInWordsDemo },
  { name: "overflow-list", title: "Overflow List", description: "Stops a “+3 more” chip list or avatar stack from hiding the item that matters by always keeping failed items, the signed-in user and pinned items visible, and spelling out what the expand button hides (“+4 more, 1 skipped”) instead of a bare count.", category: "Reading without mistakes", Demo: OverflowListDemo },
  { name: "honest-rating", title: "Honest Rating", description: "Stops shoppers trusting a bare \"4.8\" by showing how many reviews stand behind it and how they split, flagging tiny samples with the range the true score could be in, calling out love-it-or-hate-it splits, and sorting by a disclosed Bayesian score so a 5.0 from 3 reviews can't outrank a 4.6 from 900.", category: "Reading without mistakes", Demo: HonestRatingDemo },
  { name: "unit-price", title: "Unit Price", description: "Stops shoppers picking the pack that only looks cheaper by putting every option on a common unit price (₹ per 100 g, per litre or per piece), marking the true cheapest, and catching bigger packs that cost more per unit, multi-buys that cost more than singles and packs that shrank at the same price, with a one-tap switch.", category: "Reading without mistakes", Demo: UnitPriceDemo },
  { name: "abbr-hint", title: "Abbr Hint", description: "Stops readers guessing at jargon (TAT, SLA, kWh) by making each term a dotted, tappable and keyboard-focusable hint instead of a hover-only <abbr title>, spelling it out inline on first use, reading the expansion to screen readers without opening anything, and flagging abbreviations the glossary doesn't cover, with a portalled hint that is never clipped by a scrolling card or table and flips to stay on screen.", category: "Reading without mistakes", Demo: AbbrHintDemo },
  { name: "error-explainer", title: "Error Explainer", description: "Stops people stalling on (or double-submitting after) a raw error code by saying what happened, the likely cause and one next step, waiting out Retry-After, warning that an ambiguous timeout on a payment may already have gone through and offering Check status before Retry, with a support-ready copyable reference and the stack behind Technical details.", category: "Reading without mistakes", Demo: ErrorExplainerDemo },
  { name: "partial-period", title: "Partial Period", description: "Stops \"today so far vs all of yesterday\" from reading as a slump by comparing like for like (yesterday cut at the same minute) by default, warning with a one-tap fix when the full period is chosen, hatching the bucket still filling, dimming the part of yesterday not yet reached, and projecting the finish from yesterday's own curve, labelled as an estimate.", category: "Reading without mistakes", Demo: PartialPeriodDemo },
  { name: "gap-aware-line", title: "Gap-Aware Line", description: "Stops missing readings being read as a drop to zero or a smooth trend by breaking the line at nulls, shading and labelling each gap on hover and keyboard focus, keeping a lone reading between gaps visible as a dot, drawing estimated points hollow with dashed segments, and backing every reading with a data table, in pure SVG.", category: "Reading without mistakes", Demo: GapAwareLineDemo },
  { name: "fair-rank", title: "Fair Rank", description: "Stops leaderboards misleading people by ranking ties the standard competition way (1, T-2, T-2, 4) at the precision shown so equal-looking scores always share a rank, showing movement since last period with rows sliding in from where they were, and setting aside entries below a minimum sample with the reason and the rank they would have had.", category: "Reading without mistakes", Demo: FairRankDemo },
  { name: "eta-range", title: "ETA Range", description: "Stops false-precision delivery promises by quoting the range that covers 90% of deliveries with a most likely day only when one really stands out (\"Thu 15 – Sat 17 Oct, most likely Fri 16\"), counting the shipper's business days, holidays and cutoff in its own time zone, previewing the range you get after the cutoff, naming no-delivery days inside it, and explaining when the estimate widened.", category: "Reading without mistakes", Demo: EtaRangeDemo },
  { name: "palette-guard", title: "Palette Guard", description: "Stops chart series becoming indistinguishable for colour-blind readers by simulating protan, deutan and tritan vision (Machado 2009), flagging every pair under a CIEDE2000 threshold that passes Okabe–Ito, and offering the smallest lightness-only fix that clears all clashes, or patterns and direct labels when no colour change can.", category: "Reading without mistakes", Demo: PaletteGuardDemo },
]
